INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$af76771f$SATQ$, $SATQ$eb57786b-d8b8-48f4-b1d2-591b1d3ffe6b$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Sue is the nickname of a dinosaur fossil specimen housed at the Field Museum of Natural History.</li>
<li>The Field Museum of Natural History is located in Chicago, Illinois.</li>
<li>Sue is a member of the genus <em>Tyrannosaurus.</em></li>
<li>Big Mike is the nickname of a dinosaur fossil specimen housed at the Museum of the Rockies.&nbsp;</li>
<li>The Museum of the Rockies is located in Bozeman, Montana.</li>
<li>Big Mike is a member of the genus <em>Tyrannosaurus.</em></li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a similarity between the two specimens. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"9cdfecd4-c591-4358-97af-29de36b7519c","content":"<p>The Field Museum of Natural History, where Sue is housed, is located in Chicago, Illinois.</p>"},{"id":"386fbaad-fdf0-4cd1-a559-bfc7a548eabc","content":"<p>Big Mike is the nickname of a <em>Tyrannosaurus</em> fossil specimen housed at the Museum of the Rockies in Bozeman, Montana.&nbsp;</p>"},{"id":"3e8a0220-3d4b-4e31-b7cf-d2c8556f19c8","content":"<p>The dinosaur fossil specimens Sue and Big Mike are both members of the genus <em>Tyrannosaurus.</em></p>"},{"id":"80c41304-8209-4c79-a396-ae1a19ccc8de","content":"<p>While Sue is housed at the Field Museum of Natural History, Big Mike is housed at the Museum of the Rockies.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["3e8a0220-3d4b-4e31-b7cf-d2c8556f19c8"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence emphasizes a similarity between the two specimens, noting that Sue and Big Mike are members of the same genus: <em>Tyrannosaurus</em>.</p><p>Choice A is incorrect. The sentence only provides information about where one of the specimens (Sue) can be found; it doesn&rsquo;t emphasize a similarity between the two specimens. Choice B is incorrect. The sentence only provides information about one specimen (Big Mike); it doesn&rsquo;t emphasize a similarity between the two specimens. Choice D is incorrect. The sentence contrasts the locations of Sue and Big Mike; it doesn&rsquo;t emphasize a similarity between the two specimens.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"af76771f","external_id":"eb57786b-d8b8-48f4-b1d2-591b1d3ffe6b","vaultid":null,"uId":"074a27bf-57ab-4b83-8804-0cbf8d91552c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Sue is the nickname of a dinosaur fossil specimen housed at the Field Museum of Natural History.</li>\n<li>The Field Museum of Natural History is located in Chicago, Illinois.</li>\n<li>Sue is a member of the genus <em>Tyrannosaurus.</em></li>\n<li>Big Mike is the nickname of a dinosaur fossil specimen housed at the Museum of the Rockies.&nbsp;</li>\n<li>The Museum of the Rockies is located in Bozeman, Montana.</li>\n<li>Big Mike is a member of the genus <em>Tyrannosaurus.</em></li>\n</ul>","stem":"<p>The student wants to emphasize a similarity between the two specimens. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"9cdfecd4-c591-4358-97af-29de36b7519c","content":"<p>The Field Museum of Natural History, where Sue is housed, is located in Chicago, Illinois.</p>"},{"id":"386fbaad-fdf0-4cd1-a559-bfc7a548eabc","content":"<p>Big Mike is the nickname of a <em>Tyrannosaurus</em> fossil specimen housed at the Museum of the Rockies in Bozeman, Montana.&nbsp;</p>"},{"id":"3e8a0220-3d4b-4e31-b7cf-d2c8556f19c8","content":"<p>The dinosaur fossil specimens Sue and Big Mike are both members of the genus <em>Tyrannosaurus.</em></p>"},{"id":"80c41304-8209-4c79-a396-ae1a19ccc8de","content":"<p>While Sue is housed at the Field Museum of Natural History, Big Mike is housed at the Museum of the Rockies.</p>"}],"keys":["3e8a0220-3d4b-4e31-b7cf-d2c8556f19c8"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence emphasizes a similarity between the two specimens, noting that Sue and Big Mike are members of the same genus: <em>Tyrannosaurus</em>.</p><p>Choice A is incorrect. The sentence only provides information about where one of the specimens (Sue) can be found; it doesn&rsquo;t emphasize a similarity between the two specimens. Choice B is incorrect. The sentence only provides information about one specimen (Big Mike); it doesn&rsquo;t emphasize a similarity between the two specimens. Choice D is incorrect. The sentence contrasts the locations of Sue and Big Mike; it doesn&rsquo;t emphasize a similarity between the two specimens.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061192,"updateDate":1755117061192}$SATQ$::jsonb, 1755117061192, 1755117061192),
    ($SATQ$af88c47a$SATQ$, $SATQ$48c6e022-9241-4853-b508-7857271ddca7$SATQ$::uuid, $SATQ$a12ee55f-83ed-422c-a22e-b00b1967420b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Freddie Wong (born 1985) is a director and special effects artist from the United States.</li>
<li>He is best known for the action-comedy web series <em>Video Game High School</em> (<em>VGHS</em>).</li>
<li><em>VGHS </em>premiered in 2012 on RocketJump, a YouTube channel that Wong cocreated.</li>
<li>The series was celebrated for its inventive video game&ndash;centric world and high-quality special effects.</li>
<li><em>VGHS</em> was nominated for a Producers Guild Award for Outstanding Digital Series.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to begin a narrative about Wong&rsquo;s award-nominated web series. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"088c7389-5804-4fa3-913f-67c035024159","content":"<p>In 2012, director and visual effects artist Freddie Wong launched a new action-comedy web series: <em>Video Game High School.</em></p>"},{"id":"394d8f1c-882b-4bc2-8598-31a29a2d704d","content":"<p><em>Video Game High School</em> was celebrated for its inventive video game&ndash;centric world and high-quality special effects, and it was nominated for a Producer&rsquo;s Guild Award for Outstanding Digital Series.</p>"},{"id":"a033e036-5015-4b15-b3b7-73f1563389fa","content":"<p>Wong, cocreator of the YouTube channel RocketJump, would go on to see his web series be nominated for a Producers Guild Award.</p>"},{"id":"3ce9d7c4-7676-4347-8c5c-9f57ad44d0ea","content":"<p>In 2012, <em>Video Game High School</em> premiered on RocketJump; it would later be nominated for an award.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["088c7389-5804-4fa3-913f-67c035024159"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. This choice introduces Wong and <em>VGHS</em> in an active and specific way, as if to an audience unfamiliar with the series. It also sets up the time and genre of the web series, which are useful ways to introduce the series of events in a narrative. </p><p>Choice B is incorrect. This choice isn&rsquo;t suited for beginning a narrative. A narrative is a story that follows a sequence of events and creates interest and suspense for the reader. This choice jumps to the end, explaining the success of <em>VGHS</em> without explaining what it is. Choice C is incorrect. This choice isn&rsquo;t suited for beginning a narrative. It doesn&rsquo;t actually introduce the web series by name. It just jumps to later in the story without sufficient explanation. Choice D is incorrect. This choice is not very effective for beginning a narrative. It doesn&rsquo;t explain what <em>VGHS</em> is, and it doesn&rsquo;t mention Wong. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-H005$SATQ$, $SATQ$$SATQ$, $SATQ$a5266e98-4b3b-41d5-ac61-d80be66a14d0$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"af88c47a","external_id":"48c6e022-9241-4853-b508-7857271ddca7","vaultid":"a12ee55f-83ed-422c-a22e-b00b1967420b","uId":"577a7c50-317b-4d0a-b1ba-e8c964467cc7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Freddie Wong (born 1985) is a director and special effects artist from the United States.</li>\n<li>He is best known for the action-comedy web series <em>Video Game High School</em> (<em>VGHS</em>).</li>\n<li><em>VGHS </em>premiered in 2012 on RocketJump, a YouTube channel that Wong cocreated.</li>\n<li>The series was celebrated for its inventive video game&ndash;centric world and high-quality special effects.</li>\n<li><em>VGHS</em> was nominated for a Producers Guild Award for Outstanding Digital Series.</li>\n</ul>","stem":"<p>The student wants to begin a narrative about Wong&rsquo;s award-nominated web series. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"088c7389-5804-4fa3-913f-67c035024159","content":"<p>In 2012, director and visual effects artist Freddie Wong launched a new action-comedy web series: <em>Video Game High School.</em></p>"},{"id":"394d8f1c-882b-4bc2-8598-31a29a2d704d","content":"<p><em>Video Game High School</em> was celebrated for its inventive video game&ndash;centric world and high-quality special effects, and it was nominated for a Producer&rsquo;s Guild Award for Outstanding Digital Series.</p>"},{"id":"a033e036-5015-4b15-b3b7-73f1563389fa","content":"<p>Wong, cocreator of the YouTube channel RocketJump, would go on to see his web series be nominated for a Producers Guild Award.</p>"},{"id":"3ce9d7c4-7676-4347-8c5c-9f57ad44d0ea","content":"<p>In 2012, <em>Video Game High School</em> premiered on RocketJump; it would later be nominated for an award.</p>"}],"keys":["088c7389-5804-4fa3-913f-67c035024159"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. This choice introduces Wong and <em>VGHS</em> in an active and specific way, as if to an audience unfamiliar with the series. It also sets up the time and genre of the web series, which are useful ways to introduce the series of events in a narrative. </p><p>Choice B is incorrect. This choice isn&rsquo;t suited for beginning a narrative. A narrative is a story that follows a sequence of events and creates interest and suspense for the reader. This choice jumps to the end, explaining the success of <em>VGHS</em> without explaining what it is. Choice C is incorrect. This choice isn&rsquo;t suited for beginning a narrative. It doesn&rsquo;t actually introduce the web series by name. It just jumps to later in the story without sufficient explanation. Choice D is incorrect. This choice is not very effective for beginning a narrative. It doesn&rsquo;t explain what <em>VGHS</em> is, and it doesn&rsquo;t mention Wong. </p>","parenttemplatename":"OSP-KA-SYN-H005","parenttemplateid":"","templateclusterid":"a5266e98-4b3b-41d5-ac61-d80be66a14d0","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$af89fa02$SATQ$, $SATQ$f80e6575-2260-46c2-8732-dbf41d55a025$SATQ$::uuid, $SATQ$19742e93-d080-4744-9109-324ebe639b66$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The Babylonian king Hammurabi achieved much during his forty-year reign. He conquered all of Mesopotamia and built Babylon into one of the most powerful cities of the ancient world. Today, <span aria-hidden="true">______</span><span class="sr-only">blank</span> he is mainly remembered for a code of laws inscribed on a seven-foot-tall block of stone: the Code of Hammurabi.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"a4a2f8d0-8f54-4c08-a867-5074568b0c38","content":"<p>therefore,</p>"},{"id":"31accf8c-e660-4c43-bef1-6cc771261211","content":"<p>likewise,</p>"},{"id":"9a3a13f7-9b82-4fbb-8f34-d00f6b942e09","content":"<p>however,</p>"},{"id":"bcdd09bb-bab2-4983-8c1d-1a753ce4514b","content":"<p>for instance,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["9a3a13f7-9b82-4fbb-8f34-d00f6b942e09"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. &ldquo;However&rdquo; logically signals that the information in this sentence&mdash;that Hammurabi is mainly remembered for just a single achievement, the Code of Hammurabi&mdash;is contrary to what might be assumed from the previous information about Hammurabi&rsquo;s many achievements.&nbsp;</p><p>Choice A is incorrect because &ldquo;therefore&rdquo; illogically signals that the information in this sentence is a result of the previous information about Hammurabi&rsquo;s many achievements. Instead, this sentence makes a point that is contrary to what might be assumed from the previous information. Choice B is incorrect because &ldquo;likewise&rdquo; illogically signals that the information in this sentence is similar to the previous information about Hammurabi&rsquo;s many achievements. Instead, this sentence makes a point that is contrary to what might be assumed from the previous information. Choice D is incorrect because &ldquo;for instance&rdquo; illogically signals that this sentence exemplifies the previous information about Hammurabi&rsquo;s many achievements. Instead, this sentence makes a point that is contrary to what might be assumed from the previous information. </p>$SATQ$, false, 0, $SATQ$OSP-235-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$8d83bb7a-595b-4e4f-9adf-e07551043714$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"af89fa02","external_id":"f80e6575-2260-46c2-8732-dbf41d55a025","vaultid":"19742e93-d080-4744-9109-324ebe639b66","uId":"0de17cbe-195d-4148-bc32-e06b3e10a24f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The Babylonian king Hammurabi achieved much during his forty-year reign. He conquered all of Mesopotamia and built Babylon into one of the most powerful cities of the ancient world. Today, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> he is mainly remembered for a code of laws inscribed on a seven-foot-tall block of stone: the Code of Hammurabi.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"a4a2f8d0-8f54-4c08-a867-5074568b0c38","content":"<p>therefore,</p>"},{"id":"31accf8c-e660-4c43-bef1-6cc771261211","content":"<p>likewise,</p>"},{"id":"9a3a13f7-9b82-4fbb-8f34-d00f6b942e09","content":"<p>however,</p>"},{"id":"bcdd09bb-bab2-4983-8c1d-1a753ce4514b","content":"<p>for instance,</p>"}],"keys":["9a3a13f7-9b82-4fbb-8f34-d00f6b942e09"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. &ldquo;However&rdquo; logically signals that the information in this sentence&mdash;that Hammurabi is mainly remembered for just a single achievement, the Code of Hammurabi&mdash;is contrary to what might be assumed from the previous information about Hammurabi&rsquo;s many achievements.&nbsp;</p><p>Choice A is incorrect because &ldquo;therefore&rdquo; illogically signals that the information in this sentence is a result of the previous information about Hammurabi&rsquo;s many achievements. Instead, this sentence makes a point that is contrary to what might be assumed from the previous information. Choice B is incorrect because &ldquo;likewise&rdquo; illogically signals that the information in this sentence is similar to the previous information about Hammurabi&rsquo;s many achievements. Instead, this sentence makes a point that is contrary to what might be assumed from the previous information. Choice D is incorrect because &ldquo;for instance&rdquo; illogically signals that this sentence exemplifies the previous information about Hammurabi&rsquo;s many achievements. Instead, this sentence makes a point that is contrary to what might be assumed from the previous information. </p>","parenttemplatename":"OSP-235-TRA","parenttemplateid":"","templateclusterid":"8d83bb7a-595b-4e4f-9adf-e07551043714","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959333,"updateDate":1691007959333}$SATQ$::jsonb, 1691007959333, 1691007959333),
    ($SATQ$afec1a70$SATQ$, $SATQ$a2c6536c-3225-4118-a539-6618424ed9e7$SATQ$::uuid, $SATQ$e1d348cb-b35c-473e-92ea-c935772789e2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>As engineered structures, many bird nests are uniquely flexible yet cohesive.</li>
<li>A research team led by Yashraj Bhosale wanted to better understand the mechanics behind these structural properties.</li>
<li>Bhosale&rsquo;s team used laboratory models that simulated the arrangement of flexible sticks into nest-like structures.</li>
<li>The researchers analyzed the points where sticks touched one another.</li>
<li>When pressure was applied to the model nests, the number of contact points between the sticks increased, making the structures stiffer.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to present the primary aim of the research study. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"6d713136-c15a-42f8-978c-0a4f561a6a5e","content":"<p>Bhosale&rsquo;s team wanted to better understand the mechanics behind bird nests&rsquo; uniquely flexible yet cohesive structural properties.</p>"},{"id":"0a532694-fe0e-4451-babb-b537f2d49cb0","content":"<p>The researchers used laboratory models that simulated the arrangement of flexible sticks and analyzed the points where sticks touched one another.</p>"},{"id":"d1dee962-6bc7-48c3-8ca6-1d9d045cd380","content":"<p>After analyzing the points where sticks touched, the researchers found that the structures became stiffer when pressure was applied.</p>"},{"id":"cd33c7d8-4cb8-4510-beef-295219601349","content":"<p>As analyzed by Bhosale&rsquo;s team, bird nests are uniquely flexible yet cohesive engineered structures.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["6d713136-c15a-42f8-978c-0a4f561a6a5e"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. It describes the reason Bhosale&rsquo;s team wanted to study the structures of bird nests&mdash;that is to say, the study&rsquo;s primary aim. </p><p>Choice B is incorrect. This choice doesn&rsquo;t present the primary aim of the research study. It describes how the study worked, but not why it was done. Choice C is incorrect. This choice doesn&rsquo;t present the primary aim of the research study. It describes a result of the experiment, but not why it was carried out. Choice D is incorrect. This choice doesn&rsquo;t present the primary aim of the research study. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-H001$SATQ$, $SATQ$$SATQ$, $SATQ$d1828847-7b17-45cc-9791-9c79c5fd9914$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"afec1a70","external_id":"a2c6536c-3225-4118-a539-6618424ed9e7","vaultid":"e1d348cb-b35c-473e-92ea-c935772789e2","uId":"0135e4f8-5628-4716-b5c7-098c21b197a2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>As engineered structures, many bird nests are uniquely flexible yet cohesive.</li>\n<li>A research team led by Yashraj Bhosale wanted to better understand the mechanics behind these structural properties.</li>\n<li>Bhosale&rsquo;s team used laboratory models that simulated the arrangement of flexible sticks into nest-like structures.</li>\n<li>The researchers analyzed the points where sticks touched one another.</li>\n<li>When pressure was applied to the model nests, the number of contact points between the sticks increased, making the structures stiffer.</li>\n</ul>","stem":"<p>The student wants to present the primary aim of the research study. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"6d713136-c15a-42f8-978c-0a4f561a6a5e","content":"<p>Bhosale&rsquo;s team wanted to better understand the mechanics behind bird nests&rsquo; uniquely flexible yet cohesive structural properties.</p>"},{"id":"0a532694-fe0e-4451-babb-b537f2d49cb0","content":"<p>The researchers used laboratory models that simulated the arrangement of flexible sticks and analyzed the points where sticks touched one another.</p>"},{"id":"d1dee962-6bc7-48c3-8ca6-1d9d045cd380","content":"<p>After analyzing the points where sticks touched, the researchers found that the structures became stiffer when pressure was applied.</p>"},{"id":"cd33c7d8-4cb8-4510-beef-295219601349","content":"<p>As analyzed by Bhosale&rsquo;s team, bird nests are uniquely flexible yet cohesive engineered structures.</p>"}],"keys":["6d713136-c15a-42f8-978c-0a4f561a6a5e"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. It describes the reason Bhosale&rsquo;s team wanted to study the structures of bird nests&mdash;that is to say, the study&rsquo;s primary aim. </p><p>Choice B is incorrect. This choice doesn&rsquo;t present the primary aim of the research study. It describes how the study worked, but not why it was done. Choice C is incorrect. This choice doesn&rsquo;t present the primary aim of the research study. It describes a result of the experiment, but not why it was carried out. Choice D is incorrect. This choice doesn&rsquo;t present the primary aim of the research study. </p>","parenttemplatename":"OSP-KA-SYN-H001","parenttemplateid":"","templateclusterid":"d1828847-7b17-45cc-9791-9c79c5fd9914","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959371,"updateDate":1691007959371}$SATQ$::jsonb, 1691007959371, 1691007959371),
    ($SATQ$b0620764$SATQ$, $SATQ$f44c0976-8eea-4f60-9365-e7684274c4d9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Phobetor, a name drawn from Greek mythology, is an exoplanet that orbits the star PSR B1257+12, also known as Lich.</li>
<li>Phobetor&rsquo;s mass is 0.01 times that of Jupiter, or 0.01 Jupiter masses.</li>
<li>Mastika, which means &ldquo;gem&rdquo; or &ldquo;jewel&rdquo; in Malay, is an exoplanet that orbits the star HD 179949, also known as Gumala.</li>
<li>Mastika&rsquo;s mass is 0.92 Jupiter masses.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to make and support a generalization about exoplanets. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"2e9c3762-0a97-4d03-946e-3f6431c67ae8","content":"<p>Exoplanets that are named Phobetor orbit Lich, and those that are named Mastika orbit Gumala.</p>"},{"id":"cd05ff86-021c-435f-be1d-cc28b3056641","content":"<p>Even though Phobetor and Mastika are both exoplanets, their masses are different: Phobetor&rsquo;s mass is 0.01 Jupiter masses, and Mastika&rsquo;s is 0.92 Jupiter masses.</p>"},{"id":"d63a3622-e2e5-4db5-a016-ca26563ef48f","content":"<p>Many stars have both a designation and a proper name; for instance, PSR B1257+12 is also known as Lich, and HD 179949 is also known as Gumala.</p>"},{"id":"f47233a9-0e93-409d-bf55-5943f39d2555","content":"<p>Exoplanet names have diverse origins, a fact that can be seen in the cases of Phobetor, a name drawn from Greek mythology, and Mastika, which means &ldquo;gem&rdquo; or &ldquo;jewel&rdquo; in Malay.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["f47233a9-0e93-409d-bf55-5943f39d2555"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence makes and supports a generalization about exoplanets, noting that the names of exoplanets have diverse origins and supporting this with the examples of the origins of "Phobetor" and "Mastika."</p><p>Choice A is incorrect. The sentence misrepresents information from the notes, implying that there are multiple exoplanets with the same names. Additionally, the sentence provides no support for its generalization. Choice B is incorrect. The sentence contrasts the masses of two specific exoplanets; it doesn&rsquo;t make and support a generalization about exoplanets. Choice C is incorrect. The sentence makes and supports a generalization about stars, not exoplanets.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"b0620764","external_id":"f44c0976-8eea-4f60-9365-e7684274c4d9","vaultid":null,"uId":"df907c0b-cb60-48b0-af40-e2cfb0c53f7c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Phobetor, a name drawn from Greek mythology, is an exoplanet that orbits the star PSR B1257+12, also known as Lich.</li>\n<li>Phobetor&rsquo;s mass is 0.01 times that of Jupiter, or 0.01 Jupiter masses.</li>\n<li>Mastika, which means &ldquo;gem&rdquo; or &ldquo;jewel&rdquo; in Malay, is an exoplanet that orbits the star HD 179949, also known as Gumala.</li>\n<li>Mastika&rsquo;s mass is 0.92 Jupiter masses.</li>\n</ul>","stem":"<p>The student wants to make and support a generalization about exoplanets. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"2e9c3762-0a97-4d03-946e-3f6431c67ae8","content":"<p>Exoplanets that are named Phobetor orbit Lich, and those that are named Mastika orbit Gumala.</p>"},{"id":"cd05ff86-021c-435f-be1d-cc28b3056641","content":"<p>Even though Phobetor and Mastika are both exoplanets, their masses are different: Phobetor&rsquo;s mass is 0.01 Jupiter masses, and Mastika&rsquo;s is 0.92 Jupiter masses.</p>"},{"id":"d63a3622-e2e5-4db5-a016-ca26563ef48f","content":"<p>Many stars have both a designation and a proper name; for instance, PSR B1257+12 is also known as Lich, and HD 179949 is also known as Gumala.</p>"},{"id":"f47233a9-0e93-409d-bf55-5943f39d2555","content":"<p>Exoplanet names have diverse origins, a fact that can be seen in the cases of Phobetor, a name drawn from Greek mythology, and Mastika, which means &ldquo;gem&rdquo; or &ldquo;jewel&rdquo; in Malay.</p>"}],"keys":["f47233a9-0e93-409d-bf55-5943f39d2555"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence makes and supports a generalization about exoplanets, noting that the names of exoplanets have diverse origins and supporting this with the examples of the origins of \"Phobetor\" and \"Mastika.\"</p><p>Choice A is incorrect. The sentence misrepresents information from the notes, implying that there are multiple exoplanets with the same names. Additionally, the sentence provides no support for its generalization. Choice B is incorrect. The sentence contrasts the masses of two specific exoplanets; it doesn&rsquo;t make and support a generalization about exoplanets. Choice C is incorrect. The sentence makes and supports a generalization about stars, not exoplanets.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061193,"updateDate":1755117061193}$SATQ$::jsonb, 1755117061193, 1755117061193),
    ($SATQ$b07a7634$SATQ$, $SATQ$006d3b30-cede-4889-82fd-dbf2335054f4$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Digital Light Synthesis (DLS) is a form of additive manufacturing that utilizes light to rapidly cure liquid resin into high-quality, 3D objects.</li>
<li>Step 1: Ultraviolet (UV) light images are projected up into a pool of liquid resin, where the object&rsquo;s first layer takes shape.</li>
<li>Step 2: The partially cured resin object is raised, leaving a thin space (a &ldquo;dead zone&rdquo;) beneath it for oxygen and liquid resin to flow through.</li>
<li>Step 3: The UV light passes through the dead zone&mdash;maintaining the flow of resin&mdash;and partially cures additional layers of the object.</li>
<li>Step 4: When the resin object is complete, it is baked in an oven to complete the curing.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to describe how DLS cures 3D objects. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"57432a77-84f9-4aa1-a407-395fba6eaadc","content":"<p>DLS is a form of additive manufacturing that creates a &ldquo;dead zone&rdquo; in which UV light solidifies layer by layer before being baked in an oven, creating a high-quality, 3D object.</p>"},{"id":"ab94d8df-10ed-489b-bf87-b1d586f1b7e8","content":"<p>DLS cures 3D objects by passing through a &ldquo;dead zone,&rdquo; adding layers to the object, then curing the object in an oven.</p>"},{"id":"6266a6da-249f-42ab-b525-936bc58d59ce","content":"<p>In DLS, UV light images are projected into a liquid resin pool to cure a 3D object layer by layer; once solidified, the object is baked in an oven.</p>"},{"id":"61dc71a9-8dd0-425e-bcd2-db7203f978de","content":"<p>In DLS, UV light is projected into layers of liquid resin until the resin solidifies and passes through a &ldquo;dead zone,&rdquo; wherein the curing is completed.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["6266a6da-249f-42ab-b525-936bc58d59ce"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence describes how DLS cures 3D objects, noting that UV light is projected into resin to cure the object in layers, after which the object is baked to complete the curing process.</p><p>Choice A is incorrect. While the sentence does describe some elements of the curing process, the description misrepresents information in the notes; this sentence suggests that the UV light, rather than the 3D object, is baked in an oven. Choice B is incorrect. While the sentence does describe some elements of the curing process, the description misrepresents information in the notes: the UV light, not DLS, passes through the dead zone. Choice D is incorrect. While the sentence does describe some elements of the curing process, the description misrepresents information in the notes. This sentence suggests that curing is complete when the already-solidified resin passes through the dead zone; rather, liquid resin passes through the dead zone and is solidified in layers, after which curing is completed in the oven.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"b07a7634","external_id":"006d3b30-cede-4889-82fd-dbf2335054f4","vaultid":null,"uId":"244fca83-1b03-4e58-94b9-ff2fc36792da","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Digital Light Synthesis (DLS) is a form of additive manufacturing that utilizes light to rapidly cure liquid resin into high-quality, 3D objects.</li>\n<li>Step 1: Ultraviolet (UV) light images are projected up into a pool of liquid resin, where the object&rsquo;s first layer takes shape.</li>\n<li>Step 2: The partially cured resin object is raised, leaving a thin space (a &ldquo;dead zone&rdquo;) beneath it for oxygen and liquid resin to flow through.</li>\n<li>Step 3: The UV light passes through the dead zone&mdash;maintaining the flow of resin&mdash;and partially cures additional layers of the object.</li>\n<li>Step 4: When the resin object is complete, it is baked in an oven to complete the curing.</li>\n</ul>","stem":"<p>The student wants to describe how DLS cures 3D objects. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"57432a77-84f9-4aa1-a407-395fba6eaadc","content":"<p>DLS is a form of additive manufacturing that creates a &ldquo;dead zone&rdquo; in which UV light solidifies layer by layer before being baked in an oven, creating a high-quality, 3D object.</p>"},{"id":"ab94d8df-10ed-489b-bf87-b1d586f1b7e8","content":"<p>DLS cures 3D objects by passing through a &ldquo;dead zone,&rdquo; adding layers to the object, then curing the object in an oven.</p>"},{"id":"6266a6da-249f-42ab-b525-936bc58d59ce","content":"<p>In DLS, UV light images are projected into a liquid resin pool to cure a 3D object layer by layer; once solidified, the object is baked in an oven.</p>"},{"id":"61dc71a9-8dd0-425e-bcd2-db7203f978de","content":"<p>In DLS, UV light is projected into layers of liquid resin until the resin solidifies and passes through a &ldquo;dead zone,&rdquo; wherein the curing is completed.</p>"}],"keys":["6266a6da-249f-42ab-b525-936bc58d59ce"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence describes how DLS cures 3D objects, noting that UV light is projected into resin to cure the object in layers, after which the object is baked to complete the curing process.</p><p>Choice A is incorrect. While the sentence does describe some elements of the curing process, the description misrepresents information in the notes; this sentence suggests that the UV light, rather than the 3D object, is baked in an oven. Choice B is incorrect. While the sentence does describe some elements of the curing process, the description misrepresents information in the notes: the UV light, not DLS, passes through the dead zone. Choice D is incorrect. While the sentence does describe some elements of the curing process, the description misrepresents information in the notes. This sentence suggests that curing is complete when the already-solidified resin passes through the dead zone; rather, liquid resin passes through the dead zone and is solidified in layers, after which curing is completed in the oven.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061175,"updateDate":1755117061175}$SATQ$::jsonb, 1755117061175, 1755117061175),
    ($SATQ$b44141cf$SATQ$, $SATQ$e82e8e87-07e4-4651-aa1e-23f2fa389d6e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Researchers in a 2021 study wanted to determine the rate at which 17 languages conveyed both information and syllables.</li>
<li>They calculated the bits of information conveyed per second (the IR, or information rate).</li>
<li>The IR was found to be approximately consistent across the 17 languages (an average of 39 bits per second).</li>
<li>They calculated the number of syllables spoken per second (the SR, or syllable rate).</li>
<li>Spanish had the second-fastest SR (7.7 syllables per second).</li>
<li>Vietnamese had the sixteenth-fastest SR (5.3 syllables per second).</li>
</ul>$SATQ$, $SATQ$<p>The student wants to present an overview of the study&rsquo;s findings. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"f1cec1d0-c4ff-4d4d-8157-cc9693f690b9","content":"<p>The 2021 study determined the information rate (IR) of 17 languages in bits of information conveyed per second.</p>"},{"id":"02a5cc02-0428-42f6-90c9-7320df4b3af2","content":"<p>Researchers found that information was conveyed more quickly in Spanish, at 7.7 syllables per second, than in Vietnamese, at 5.3 syllables per second.</p>"},{"id":"7bba5f83-95a8-4d49-ba51-c176af3f3a4a","content":"<p>Vietnamese had the sixteenth-fastest syllable rate, lower than that of Spanish, which had the second-fastest; however, Spanish had the lower information rate of the two.</p>"},{"id":"42de861d-9759-4041-a51d-f2b50bb76f29","content":"<p>Though some of the languages differed in number of syllables spoken per second, all 17 conveyed information at roughly the same rate.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["42de861d-9759-4041-a51d-f2b50bb76f29"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence presents an overview of the study&rsquo;s findings, noting that, for some of the languages (the examples of Spanish and Vietnamese are given in the notes), the number of syllables spoken per second varied, while the amount of information conveyed per second remained roughly constant across all 17 languages.</p><p>Choice A is incorrect. While the sentence describes one of the metrics the study assessed, it doesn&rsquo;t present any of the study&rsquo;s findings. Choice B is incorrect. While the sentence compares specific findings about two of the languages studied, it doesn&rsquo;t provide an overview of the study&rsquo;s findings across all 17 languages. Choice C is incorrect. The sentence compares specific findings about two of the languages studied; it doesn&rsquo;t provide an overview of the study&rsquo;s findings across all 17 languages. It also misrepresents the information from the notes about Spanish&rsquo;s information rate.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"b44141cf","external_id":"e82e8e87-07e4-4651-aa1e-23f2fa389d6e","vaultid":null,"uId":"c85a3470-b8ea-4c1f-ab2d-9a627e124753","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Researchers in a 2021 study wanted to determine the rate at which 17 languages conveyed both information and syllables.</li>\n<li>They calculated the bits of information conveyed per second (the IR, or information rate).</li>\n<li>The IR was found to be approximately consistent across the 17 languages (an average of 39 bits per second).</li>\n<li>They calculated the number of syllables spoken per second (the SR, or syllable rate).</li>\n<li>Spanish had the second-fastest SR (7.7 syllables per second).</li>\n<li>Vietnamese had the sixteenth-fastest SR (5.3 syllables per second).</li>\n</ul>","stem":"<p>The student wants to present an overview of the study&rsquo;s findings. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"f1cec1d0-c4ff-4d4d-8157-cc9693f690b9","content":"<p>The 2021 study determined the information rate (IR) of 17 languages in bits of information conveyed per second.</p>"},{"id":"02a5cc02-0428-42f6-90c9-7320df4b3af2","content":"<p>Researchers found that information was conveyed more quickly in Spanish, at 7.7 syllables per second, than in Vietnamese, at 5.3 syllables per second.</p>"},{"id":"7bba5f83-95a8-4d49-ba51-c176af3f3a4a","content":"<p>Vietnamese had the sixteenth-fastest syllable rate, lower than that of Spanish, which had the second-fastest; however, Spanish had the lower information rate of the two.</p>"},{"id":"42de861d-9759-4041-a51d-f2b50bb76f29","content":"<p>Though some of the languages differed in number of syllables spoken per second, all 17 conveyed information at roughly the same rate.</p>"}],"keys":["42de861d-9759-4041-a51d-f2b50bb76f29"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence presents an overview of the study&rsquo;s findings, noting that, for some of the languages (the examples of Spanish and Vietnamese are given in the notes), the number of syllables spoken per second varied, while the amount of information conveyed per second remained roughly constant across all 17 languages.</p><p>Choice A is incorrect. While the sentence describes one of the metrics the study assessed, it doesn&rsquo;t present any of the study&rsquo;s findings. Choice B is incorrect. While the sentence compares specific findings about two of the languages studied, it doesn&rsquo;t provide an overview of the study&rsquo;s findings across all 17 languages. Choice C is incorrect. The sentence compares specific findings about two of the languages studied; it doesn&rsquo;t provide an overview of the study&rsquo;s findings across all 17 languages. It also misrepresents the information from the notes about Spanish&rsquo;s information rate.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669214,"updateDate":1743430669214}$SATQ$::jsonb, 1743430669214, 1743430669214),
    ($SATQ$b46e0c8a$SATQ$, $SATQ$82e1e63f-f666-42ba-8165-017edd1a30e4$SATQ$::uuid, $SATQ$c40b8a57-73b5-46c6-89a3-8ae5baaf714a$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Organisms release cellular material into their environment by shedding substances such as hair or skin.</li>
<li>The DNA in these substances is known as environmental DNA, or eDNA.</li>
<li>Researchers collect and analyze eDNA to detect the presence of species that are difficult to observe.</li>
<li>Geneticist Sara Oyler-McCance&rsquo;s research team analyzed eDNA in water samples from the Florida Everglades to detect invasive constrictor snake species in the area.</li>
<li>The study determined a 91% probability of detecting Burmese python eDNA in a given location.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to present the study to an audience already familiar with environmental DNA. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"6273d1a6-9542-4106-bce6-392f2aa4b871","content":"<p>Sara Oyler-McCance&rsquo;s researchers analyzed eDNA in water samples from the Florida Everglades for evidence of invasive constrictor snakes, which are difficult to observe.</p>"},{"id":"1f020427-0ee1-40dc-b925-6cdc69b332fe","content":"<p>An analysis of eDNA can detect the presence of invasive species that are difficult to observe, such as constrictor snakes.</p>"},{"id":"2e001f47-2b6e-4364-8f3a-38a56cad81ee","content":"<p>Researchers found Burmese python eDNA, or environmental DNA, in water samples; eDNA is the DNA in released cellular materials, such as shed skin cells.</p>"},{"id":"86aa37f5-cb5e-4bd7-ab23-2e2d33e87502","content":"<p>Sara Oyler-McCance&rsquo;s researchers analyzed environmental DNA (eDNA)&mdash;that is, DNA from cellular materials released by organisms&mdash;in water samples from the Florida Everglades.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["6273d1a6-9542-4106-bce6-392f2aa4b871"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. This choice presents the study in a way that assumes the audience is already familiar with eDNA.</p><p>Choice B is incorrect. This choice doesn&rsquo;t present the study. It only states a general fact about eDNA analysis. Choice C is incorrect. This choice isn&rsquo;t suited for an audience already familiar with eDNA. A familiar audience wouldn&rsquo;t need to have the term defined or explained. Choice D is incorrect. This choice isn&rsquo;t suited for an audience already familiar with eDNA. A familiar audience wouldn&rsquo;t need to have the term defined or explained. It also doesn&rsquo;t present the study.</p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-M010$SATQ$, $SATQ$$SATQ$, $SATQ$be242423-7b74-482b-bf17-74fbe7c08445$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"b46e0c8a","external_id":"82e1e63f-f666-42ba-8165-017edd1a30e4","vaultid":"c40b8a57-73b5-46c6-89a3-8ae5baaf714a","uId":"084f05da-405f-4f5f-94d5-107eb76e1ac5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Organisms release cellular material into their environment by shedding substances such as hair or skin.</li>\n<li>The DNA in these substances is known as environmental DNA, or eDNA.</li>\n<li>Researchers collect and analyze eDNA to detect the presence of species that are difficult to observe.</li>\n<li>Geneticist Sara Oyler-McCance&rsquo;s research team analyzed eDNA in water samples from the Florida Everglades to detect invasive constrictor snake species in the area.</li>\n<li>The study determined a 91% probability of detecting Burmese python eDNA in a given location.</li>\n</ul>","stem":"<p>The student wants to present the study to an audience already familiar with environmental DNA. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"6273d1a6-9542-4106-bce6-392f2aa4b871","content":"<p>Sara Oyler-McCance&rsquo;s researchers analyzed eDNA in water samples from the Florida Everglades for evidence of invasive constrictor snakes, which are difficult to observe.</p>"},{"id":"1f020427-0ee1-40dc-b925-6cdc69b332fe","content":"<p>An analysis of eDNA can detect the presence of invasive species that are difficult to observe, such as constrictor snakes.</p>"},{"id":"2e001f47-2b6e-4364-8f3a-38a56cad81ee","content":"<p>Researchers found Burmese python eDNA, or environmental DNA, in water samples; eDNA is the DNA in released cellular materials, such as shed skin cells.</p>"},{"id":"86aa37f5-cb5e-4bd7-ab23-2e2d33e87502","content":"<p>Sara Oyler-McCance&rsquo;s researchers analyzed environmental DNA (eDNA)&mdash;that is, DNA from cellular materials released by organisms&mdash;in water samples from the Florida Everglades.</p>"}],"keys":["6273d1a6-9542-4106-bce6-392f2aa4b871"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. This choice presents the study in a way that assumes the audience is already familiar with eDNA.</p><p>Choice B is incorrect. This choice doesn&rsquo;t present the study. It only states a general fact about eDNA analysis. Choice C is incorrect. This choice isn&rsquo;t suited for an audience already familiar with eDNA. A familiar audience wouldn&rsquo;t need to have the term defined or explained. Choice D is incorrect. This choice isn&rsquo;t suited for an audience already familiar with eDNA. A familiar audience wouldn&rsquo;t need to have the term defined or explained. It also doesn&rsquo;t present the study.</p>","parenttemplatename":"OSP-KA-SYN-M010","parenttemplateid":"","templateclusterid":"be242423-7b74-482b-bf17-74fbe7c08445","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$b5972710$SATQ$, $SATQ$894dc07c-a264-42f2-a4c5-ee2c52f02f11$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Niger ratified the Outer Space Treaty, an international agreement with over 100 signing nations that acts as the foundation for the laws of space, on February 1, 1967. Jordan, <span aria-hidden="true">______</span><span class="sr-only">blank</span> has yet to officially ratify the treaty; it only signed it.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"91f9ba74-d659-48db-a145-dd349f3b5d59","content":"<p>in contrast,</p>"},{"id":"e9608fe4-4dc4-40a5-92e1-11002d5746fc","content":"<p>specifically,</p>"},{"id":"1cc040e7-104f-4b21-865b-765543e50780","content":"<p>for example,</p>"},{"id":"5eb3f816-da56-483d-b0d7-f4aee12f7200","content":"<p>similarly,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["91f9ba74-d659-48db-a145-dd349f3b5d59"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. "In contrast" logically signals that the information in this sentence&mdash;that Jordan has yet to officially ratify the treaty&mdash;contrasts with the previous information about Niger having already ratified the treaty.</p><p>Choice B is incorrect because "specifically" illogically signals that the information in this sentence specifies or elaborates on the previous information about Niger ratifying the treaty. Instead, the sentence changes subjects from Niger to Jordan, presenting contrasting information about Jordan&rsquo;s treaty status. Choice C is incorrect because "for example" illogically signals that the information in this sentence exemplifies the previous information about Niger ratifying the treaty. Instead, the sentence explains that Jordan has yet to ratify the treaty. Choice D is incorrect because "similarly" illogically signals that the information in this sentence is similar to the previous information about Niger ratifying the treaty. Instead, the sentence presents contrasting information that Jordan has yet to ratify the treaty.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"b5972710","external_id":"894dc07c-a264-42f2-a4c5-ee2c52f02f11","vaultid":null,"uId":"c2c593f0-1ef1-4f3f-b3de-cd7e130ea509","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Niger ratified the Outer Space Treaty, an international agreement with over 100 signing nations that acts as the foundation for the laws of space, on February 1, 1967. Jordan, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> has yet to officially ratify the treaty; it only signed it.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"91f9ba74-d659-48db-a145-dd349f3b5d59","content":"<p>in contrast,</p>"},{"id":"e9608fe4-4dc4-40a5-92e1-11002d5746fc","content":"<p>specifically,</p>"},{"id":"1cc040e7-104f-4b21-865b-765543e50780","content":"<p>for example,</p>"},{"id":"5eb3f816-da56-483d-b0d7-f4aee12f7200","content":"<p>similarly,</p>"}],"keys":["91f9ba74-d659-48db-a145-dd349f3b5d59"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. \"In contrast\" logically signals that the information in this sentence&mdash;that Jordan has yet to officially ratify the treaty&mdash;contrasts with the previous information about Niger having already ratified the treaty.</p><p>Choice B is incorrect because \"specifically\" illogically signals that the information in this sentence specifies or elaborates on the previous information about Niger ratifying the treaty. Instead, the sentence changes subjects from Niger to Jordan, presenting contrasting information about Jordan&rsquo;s treaty status. Choice C is incorrect because \"for example\" illogically signals that the information in this sentence exemplifies the previous information about Niger ratifying the treaty. Instead, the sentence explains that Jordan has yet to ratify the treaty. Choice D is incorrect because \"similarly\" illogically signals that the information in this sentence is similar to the previous information about Niger ratifying the treaty. Instead, the sentence presents contrasting information that Jordan has yet to ratify the treaty.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061189,"updateDate":1755117061189}$SATQ$::jsonb, 1755117061189, 1755117061189),
    ($SATQ$b5a399f1$SATQ$, $SATQ$3af242c2-e93e-445c-b15f-b7ddf46f46fb$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Following the Mata Ortiz pottery technique, Mexican sculptor Juan Quezada Celado starts by creating the base of the pot with a slab of clay. <span aria-hidden="true">______</span><span class="sr-only">blank</span> he builds the pot walls by layering coils of clay around the perimeter of the base. Celado then smooths out the pot&rsquo;s walls with a hacksaw blade. At last, the pot is ready to be painted.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"ae6a81fd-508e-4c08-8cb0-f0b460dfcb07","content":"<p>For example,</p>"},{"id":"6149c8cb-f1a8-4104-b809-1de64d0bda5a","content":"<p>However,</p>"},{"id":"fc4bdfa4-db68-4fe9-9f7f-02a182cfd6a4","content":"<p>By contrast,</p>"},{"id":"dd3ea2ed-c4e2-4291-a717-50ad9e4c0e41","content":"<p>Next,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["dd3ea2ed-c4e2-4291-a717-50ad9e4c0e41"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "Next" logically signals that the information in this sentence&mdash;which explains how Celado builds the pot&rsquo;s walls&mdash;is the next step in Celado&rsquo;s pot creation process. The sentences that follow further signal this information by completing the process.</p><p>Choice A is incorrect because "for example" illogically signals that the information about Celado building pot walls in this sentence exemplifies the information in the previous sentence about how Celado&rsquo;s pot creation process begins. Instead, it is the next step in this process. Choice B is incorrect because "however" illogically signals that the information in this sentence contrasts with the information in the previous sentence about how Celado&rsquo;s pot creation process begins. Instead, it is the next step in this process. Choice C is incorrect because "by contrast" illogically signals that the information in this sentence contrasts with the information in the previous sentence about how Celado&rsquo;s pot creation process begins. Instead, it is the next step in this process.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"b5a399f1","external_id":"3af242c2-e93e-445c-b15f-b7ddf46f46fb","vaultid":null,"uId":"ec47ae56-fcc7-4051-9914-b5f3b0c79ee6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Following the Mata Ortiz pottery technique, Mexican sculptor Juan Quezada Celado starts by creating the base of the pot with a slab of clay. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> he builds the pot walls by layering coils of clay around the perimeter of the base. Celado then smooths out the pot&rsquo;s walls with a hacksaw blade. At last, the pot is ready to be painted.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"ae6a81fd-508e-4c08-8cb0-f0b460dfcb07","content":"<p>For example,</p>"},{"id":"6149c8cb-f1a8-4104-b809-1de64d0bda5a","content":"<p>However,</p>"},{"id":"fc4bdfa4-db68-4fe9-9f7f-02a182cfd6a4","content":"<p>By contrast,</p>"},{"id":"dd3ea2ed-c4e2-4291-a717-50ad9e4c0e41","content":"<p>Next,</p>"}],"keys":["dd3ea2ed-c4e2-4291-a717-50ad9e4c0e41"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"Next\" logically signals that the information in this sentence&mdash;which explains how Celado builds the pot&rsquo;s walls&mdash;is the next step in Celado&rsquo;s pot creation process. The sentences that follow further signal this information by completing the process.</p><p>Choice A is incorrect because \"for example\" illogically signals that the information about Celado building pot walls in this sentence exemplifies the information in the previous sentence about how Celado&rsquo;s pot creation process begins. Instead, it is the next step in this process. Choice B is incorrect because \"however\" illogically signals that the information in this sentence contrasts with the information in the previous sentence about how Celado&rsquo;s pot creation process begins. Instead, it is the next step in this process. Choice C is incorrect because \"by contrast\" illogically signals that the information in this sentence contrasts with the information in the previous sentence about how Celado&rsquo;s pot creation process begins. Instead, it is the next step in this process.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323044,"updateDate":1730147323044}$SATQ$::jsonb, 1730147323044, 1730147323044),
    ($SATQ$b5cd28a7$SATQ$, $SATQ$109b9f2a-fd55-4d02-993a-4858b324cfa4$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Samuel Delany is a US writer known for his science fiction.</li>
<li>Delany&rsquo;s science fiction novel <em>Babel-17</em> was published in 1966.</li>
<li>The novel won a Nebula Award in 1967.</li>
<li>The Nebula Awards are given each year to the best works of science fiction published in the US.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to indicate the title of a novel that won a Nebula Award. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"3bd0584f-9994-42fa-a2da-6020b1f922ca","content":"<p><em>Babel-17</em>, by Samuel Delany, won a Nebula Award in 1967.</p>"},{"id":"a996fa72-3c52-417a-87d1-b9d373e202eb","content":"<p>Samuel Delany published a science fiction novel in 1966.</p>"},{"id":"7dc5634b-2076-4ba4-9a1b-b9f86ae9f82b","content":"<p>Samuel Delany is an award-winning US writer known for his science fiction.</p>"},{"id":"b3ed1000-1029-44fb-a781-a95a8bc8a393","content":"<p>One of Samuel Delany&rsquo;s novels was among the best works of science fiction published in the US.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["3bd0584f-9994-42fa-a2da-6020b1f922ca"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence indicates the title of a novel that won a Nebula Award, noting that <em>Babel-17</em> by Samuel Delany won the award in 1967.</p><p>Choice B is incorrect because the sentence identifies the year that Samuel Delany published a science fiction novel; it doesn&rsquo;t indicate the novel&rsquo;s title or that it won a Nebula Award. Choice C is incorrect because the sentence provides an introduction of Samuel Delany; it doesn&rsquo;t indicate the title of a novel that has won a Nebula Award. Choice D is incorrect because the sentence indicates that one of Samuel Delany&rsquo;s novels met the qualification for a Nebula Award; it doesn&rsquo;t indicate the novel&rsquo;s title or that it won an award.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"b5cd28a7","external_id":"109b9f2a-fd55-4d02-993a-4858b324cfa4","vaultid":null,"uId":"81fa5899-5f2a-4288-b010-64f8d3df5f06","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Samuel Delany is a US writer known for his science fiction.</li>\n<li>Delany&rsquo;s science fiction novel <em>Babel-17</em> was published in 1966.</li>\n<li>The novel won a Nebula Award in 1967.</li>\n<li>The Nebula Awards are given each year to the best works of science fiction published in the US.</li>\n</ul>","stem":"<p>The student wants to indicate the title of a novel that won a Nebula Award. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"3bd0584f-9994-42fa-a2da-6020b1f922ca","content":"<p><em>Babel-17</em>, by Samuel Delany, won a Nebula Award in 1967.</p>"},{"id":"a996fa72-3c52-417a-87d1-b9d373e202eb","content":"<p>Samuel Delany published a science fiction novel in 1966.</p>"},{"id":"7dc5634b-2076-4ba4-9a1b-b9f86ae9f82b","content":"<p>Samuel Delany is an award-winning US writer known for his science fiction.</p>"},{"id":"b3ed1000-1029-44fb-a781-a95a8bc8a393","content":"<p>One of Samuel Delany&rsquo;s novels was among the best works of science fiction published in the US.</p>"}],"keys":["3bd0584f-9994-42fa-a2da-6020b1f922ca"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence indicates the title of a novel that won a Nebula Award, noting that <em>Babel-17</em> by Samuel Delany won the award in 1967.</p><p>Choice B is incorrect because the sentence identifies the year that Samuel Delany published a science fiction novel; it doesn&rsquo;t indicate the novel&rsquo;s title or that it won a Nebula Award. Choice C is incorrect because the sentence provides an introduction of Samuel Delany; it doesn&rsquo;t indicate the title of a novel that has won a Nebula Award. Choice D is incorrect because the sentence indicates that one of Samuel Delany&rsquo;s novels met the qualification for a Nebula Award; it doesn&rsquo;t indicate the novel&rsquo;s title or that it won an award.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669203,"updateDate":1743430669203}$SATQ$::jsonb, 1743430669203, 1743430669203),
    ($SATQ$b6ebadf6$SATQ$, $SATQ$56f57e4d-f877-4137-a307-e5b681487dd3$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>There are three basic steps you should follow when planning a scientific inquiry. First, thoroughly research the question you wish to answer. <span aria-hidden="true">______</span><span class="sr-only">blank</span> come up with a prediction (also called a hypothesis) about the answer to your question. Third, develop an experiment that can test the accuracy of your hypothesis.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"ed5ba619-1b92-446f-8c2b-f2129f04191f","content":"<p>Therefore,</p>"},{"id":"364334ab-0505-48f4-9cf1-266de0671a6d","content":"<p>Instead,</p>"},{"id":"962dada8-dbf3-4141-85d6-f471d55df516","content":"<p>For example,</p>"},{"id":"1ca1cc0c-5b1a-441c-903a-72a79248a52a","content":"<p>Second,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["1ca1cc0c-5b1a-441c-903a-72a79248a52a"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "Second" logically signals that the activity described in this sentence&mdash;coming up with a prediction&mdash;is the next step in the three-part sequence of steps described in the text.</p><p>Choice A is incorrect because "therefore" illogically signals that coming up with a prediction is a result or consequence of the activity described in the previous sentence: researching a question. While a prediction may be influenced by prior research, these activities are distinct steps in planning a scientific inquiry. Coming up with a prediction is the next step in the three-part sequence of steps described in the text. Choice B is incorrect because "instead" illogically signals that coming up with a prediction is an alternative to the activity described in the previous sentence: researching a question. Rather, coming up with a prediction is the next step in the three-part sequence of steps described in the text. Choice C is incorrect because "for example" illogically signals that coming up with a prediction is an example of the activity described in the previous sentence: researching a question. Instead, coming up with a prediction is the next step in the three-part sequence of steps described in the text.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"b6ebadf6","external_id":"56f57e4d-f877-4137-a307-e5b681487dd3","vaultid":null,"uId":"cd5bade8-ee53-4508-a34e-532622f7ebe1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>There are three basic steps you should follow when planning a scientific inquiry. First, thoroughly research the question you wish to answer. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> come up with a prediction (also called a hypothesis) about the answer to your question. Third, develop an experiment that can test the accuracy of your hypothesis.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"ed5ba619-1b92-446f-8c2b-f2129f04191f","content":"<p>Therefore,</p>"},{"id":"364334ab-0505-48f4-9cf1-266de0671a6d","content":"<p>Instead,</p>"},{"id":"962dada8-dbf3-4141-85d6-f471d55df516","content":"<p>For example,</p>"},{"id":"1ca1cc0c-5b1a-441c-903a-72a79248a52a","content":"<p>Second,</p>"}],"keys":["1ca1cc0c-5b1a-441c-903a-72a79248a52a"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"Second\" logically signals that the activity described in this sentence&mdash;coming up with a prediction&mdash;is the next step in the three-part sequence of steps described in the text.</p><p>Choice A is incorrect because \"therefore\" illogically signals that coming up with a prediction is a result or consequence of the activity described in the previous sentence: researching a question. While a prediction may be influenced by prior research, these activities are distinct steps in planning a scientific inquiry. Coming up with a prediction is the next step in the three-part sequence of steps described in the text. Choice B is incorrect because \"instead\" illogically signals that coming up with a prediction is an alternative to the activity described in the previous sentence: researching a question. Rather, coming up with a prediction is the next step in the three-part sequence of steps described in the text. Choice C is incorrect because \"for example\" illogically signals that coming up with a prediction is an example of the activity described in the previous sentence: researching a question. Instead, coming up with a prediction is the next step in the three-part sequence of steps described in the text.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669207,"updateDate":1743430669207}$SATQ$::jsonb, 1743430669207, 1743430669207),
    ($SATQ$b7571c0a$SATQ$, $SATQ$b0cd1d34-da58-4d8c-aca5-e234f05ac2f2$SATQ$::uuid, $SATQ$d469c753-6d82-4db5-9e92-b2a18326c668$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Practical movie effects, such as the use of actual locations in a film, provide a more realistic visual experience than computer-generated imagery (CGI) does, but giving audiences the &ldquo;real thing&rdquo; can be prohibitively expensive. <span aria-hidden="true">______</span><span class="sr-only">blank</span> many filmmakers use a blended approach, employing practical effects whenever possible and CGI elements as necessary to control costs.  </p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"0e10cec5-bf93-4f52-b6ba-45315c0feb77","content":"<p>Similarly,</p>"},{"id":"772cca76-23d5-4873-8af4-7ffd17b0fe98","content":"<p>For this reason,</p>"},{"id":"b51bb679-283b-4f9c-8a64-b093e3057cd6","content":"<p>Furthermore,</p>"},{"id":"78ed8c2e-6b5f-4398-a84f-e118d03a8870","content":"<p>In other words,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["772cca76-23d5-4873-8af4-7ffd17b0fe98"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The first sentence tells us that practical effects are more realistic but also more expensive than CGI. The second sentence tells us that many filmmakers use both kinds of effects, balancing realism with cost. To connect these ideas, we need a cause-and-effect transition, like &ldquo;therefore.&rdquo; &ldquo;For this reason&rdquo; has the same meaning as &ldquo;therefore.&rdquo;&nbsp;. </p><p>Choice A is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that practical effects are more realistic but also more expensive than CGI. The second sentence tells us that many filmmakers use both kinds of effects, balancing realism with cost. To connect these ideas, we need a cause-and-effect transition, like &ldquo;therefore.&rdquo; &ldquo;Similarly&rdquo; doesn&rsquo;t show cause and effect: it shows the addition of another agreeing idea.&nbsp;Choice C is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that practical effects are more realistic but also more expensive than CGI. The second sentence tells us that many filmmakers use both kinds of effects, balancing realism with cost. To connect these ideas, we need a cause-and-effect transition, like &ldquo;therefore.&rdquo; &ldquo;Furthermore&rdquo; doesn&rsquo;t show cause and effect: it shows the addition of another agreeing idea.&nbsp;Choice D is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that practical effects are more realistic but also more expensive than CGI. The second sentence tells us that many filmmakers use both kinds of effects, balancing realism with cost. To connect these ideas, we need a cause-and-effect transition, like &ldquo;therefore.&rdquo; &ldquo;In other words&rdquo; doesn&rsquo;t show cause and effect: it shows a restatement of the same idea in different words.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-200-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$6043ef1d-a25d-46b9-8b45-ae3cf54d1922$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"b7571c0a","external_id":"b0cd1d34-da58-4d8c-aca5-e234f05ac2f2","vaultid":"d469c753-6d82-4db5-9e92-b2a18326c668","uId":"9556a785-1153-45b9-adfc-df72997f0ee7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Practical movie effects, such as the use of actual locations in a film, provide a more realistic visual experience than computer-generated imagery (CGI) does, but giving audiences the &ldquo;real thing&rdquo; can be prohibitively expensive. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> many filmmakers use a blended approach, employing practical effects whenever possible and CGI elements as necessary to control costs.  </p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"0e10cec5-bf93-4f52-b6ba-45315c0feb77","content":"<p>Similarly,</p>"},{"id":"772cca76-23d5-4873-8af4-7ffd17b0fe98","content":"<p>For this reason,</p>"},{"id":"b51bb679-283b-4f9c-8a64-b093e3057cd6","content":"<p>Furthermore,</p>"},{"id":"78ed8c2e-6b5f-4398-a84f-e118d03a8870","content":"<p>In other words,</p>"}],"keys":["772cca76-23d5-4873-8af4-7ffd17b0fe98"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The first sentence tells us that practical effects are more realistic but also more expensive than CGI. The second sentence tells us that many filmmakers use both kinds of effects, balancing realism with cost. To connect these ideas, we need a cause-and-effect transition, like &ldquo;therefore.&rdquo; &ldquo;For this reason&rdquo; has the same meaning as &ldquo;therefore.&rdquo;&nbsp;. </p><p>Choice A is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that practical effects are more realistic but also more expensive than CGI. The second sentence tells us that many filmmakers use both kinds of effects, balancing realism with cost. To connect these ideas, we need a cause-and-effect transition, like &ldquo;therefore.&rdquo; &ldquo;Similarly&rdquo; doesn&rsquo;t show cause and effect: it shows the addition of another agreeing idea.&nbsp;Choice C is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that practical effects are more realistic but also more expensive than CGI. The second sentence tells us that many filmmakers use both kinds of effects, balancing realism with cost. To connect these ideas, we need a cause-and-effect transition, like &ldquo;therefore.&rdquo; &ldquo;Furthermore&rdquo; doesn&rsquo;t show cause and effect: it shows the addition of another agreeing idea.&nbsp;Choice D is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that practical effects are more realistic but also more expensive than CGI. The second sentence tells us that many filmmakers use both kinds of effects, balancing realism with cost. To connect these ideas, we need a cause-and-effect transition, like &ldquo;therefore.&rdquo; &ldquo;In other words&rdquo; doesn&rsquo;t show cause and effect: it shows a restatement of the same idea in different words.&nbsp;</p>","parenttemplatename":"OSP-200-TRA","parenttemplateid":"","templateclusterid":"6043ef1d-a25d-46b9-8b45-ae3cf54d1922","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959325,"updateDate":1691007959325}$SATQ$::jsonb, 1691007959325, 1691007959325),
    ($SATQ$b7c404d1$SATQ$, $SATQ$5092086e-9e04-41e3-be32-ea196b3e50e7$SATQ$::uuid, $SATQ$6afa030d-1ebb-4598-b782-765acd882f09$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>With her room-sized installation <em>The Interstitium</em>, Iranian American artist Laleh Mehran succeeded in creating a space that felt, as intended, both &ldquo;familiar and distant.&rdquo; <span aria-hidden="true">______</span><span class="sr-only">blank</span> with a video screen placed at the far end of the coal slag-encrusted room, her installation was reminiscent of a typical movie theater&mdash;albeit one found in a subterranean coal mine.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"5ef80259-fe5b-4ca4-8d71-80de67781843","content":"<p>Next,</p>"},{"id":"322a8c62-abdb-4f12-8343-4ab724838ef9","content":"<p>Nevertheless,</p>"},{"id":"63bcb6c2-61ce-4e1f-993d-0d03cdbf5cf6","content":"<p>Indeed,</p>"},{"id":"21e354b0-fc2d-4de4-a3cd-f8fdd0c0aa26","content":"<p>Instead,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["63bcb6c2-61ce-4e1f-993d-0d03cdbf5cf6"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. "Indeed" logically signals that the information in this sentence&mdash;that Laleh Mehran&rsquo;s installation resembled both a typical movie theater and a coal mine&mdash;supports the previous sentence&rsquo;s claim that the space Mehran created felt both "familiar and distant."</p><p>Choice A is incorrect because "next" illogically signals that the description of Laleh Mehran&rsquo;s installation in this sentence is the next step in a process. Rather, it supports the previous sentence&rsquo;s claim about Mehran&rsquo;s installation. Choice B is incorrect because "nevertheless" illogically signals that the information in this sentence is true despite the claim about Laleh Mehran&rsquo;s installation in the previous sentence. Rather, it supports that claim. Choice D is incorrect because "instead" illogically signals that this sentence presents an alternative to the previous sentence&rsquo;s claim about Laleh Mehran&rsquo;s installation. Rather, it supports that claim.</p>$SATQ$, false, 0, $SATQ$OSP-271-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$091dde4b-492a-4571-bfd9-e5c4cf8868d0$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"b7c404d1","external_id":"5092086e-9e04-41e3-be32-ea196b3e50e7","vaultid":"6afa030d-1ebb-4598-b782-765acd882f09","uId":"ac95b1dd-fdd2-4fe8-ba49-a0ec5a45f336","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>With her room-sized installation <em>The Interstitium</em>, Iranian American artist Laleh Mehran succeeded in creating a space that felt, as intended, both &ldquo;familiar and distant.&rdquo; <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> with a video screen placed at the far end of the coal slag-encrusted room, her installation was reminiscent of a typical movie theater&mdash;albeit one found in a subterranean coal mine.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"5ef80259-fe5b-4ca4-8d71-80de67781843","content":"<p>Next,</p>"},{"id":"322a8c62-abdb-4f12-8343-4ab724838ef9","content":"<p>Nevertheless,</p>"},{"id":"63bcb6c2-61ce-4e1f-993d-0d03cdbf5cf6","content":"<p>Indeed,</p>"},{"id":"21e354b0-fc2d-4de4-a3cd-f8fdd0c0aa26","content":"<p>Instead,</p>"}],"keys":["63bcb6c2-61ce-4e1f-993d-0d03cdbf5cf6"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. \"Indeed\" logically signals that the information in this sentence&mdash;that Laleh Mehran&rsquo;s installation resembled both a typical movie theater and a coal mine&mdash;supports the previous sentence&rsquo;s claim that the space Mehran created felt both \"familiar and distant.\"</p><p>Choice A is incorrect because \"next\" illogically signals that the description of Laleh Mehran&rsquo;s installation in this sentence is the next step in a process. Rather, it supports the previous sentence&rsquo;s claim about Mehran&rsquo;s installation. Choice B is incorrect because \"nevertheless\" illogically signals that the information in this sentence is true despite the claim about Laleh Mehran&rsquo;s installation in the previous sentence. Rather, it supports that claim. Choice D is incorrect because \"instead\" illogically signals that this sentence presents an alternative to the previous sentence&rsquo;s claim about Laleh Mehran&rsquo;s installation. Rather, it supports that claim.</p>","parenttemplatename":"OSP-271-TRA","parenttemplateid":"","templateclusterid":"091dde4b-492a-4571-bfd9-e5c4cf8868d0","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959334,"updateDate":1691007959334}$SATQ$::jsonb, 1691007959334, 1691007959334),
    ($SATQ$b88dad9d$SATQ$, $SATQ$075003df-5e06-4b3f-88b4-1a859b06ea0d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Al-Andalus, the historical region of the Iberian Peninsula that includes most of modern-day Spain, was ruled by various Arabic-speaking Muslim states between the eighth and fifteenth centuries. <span aria-hidden="true">______</span><span class="sr-only">blank</span> many Arabic words, such as &ldquo;alacr&aacute;n&rdquo;&mdash;meaning &ldquo;scorpion&rdquo;&mdash;made their way into the Spanish language.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"aded8720-0d42-4254-ae1d-84883db308e9","content":"<p>For example,</p>"},{"id":"4bce628d-c873-475a-bae6-a69aa823b0ce","content":"<p>Instead,</p>"},{"id":"2ed7b190-42eb-4b86-9c04-108931e2cadc","content":"<p>Specifically,</p>"},{"id":"061bfb10-cfe0-4d62-9edd-07afeacacc8f","content":"<p>Consequently,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["061bfb10-cfe0-4d62-9edd-07afeacacc8f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;Consequently&rdquo; logically signals that the information in this sentence&mdash;that many Arabic words entered the Spanish language&mdash;is a result or consequence of the previous information about Arabic-speaking Muslim states ruling Al-Andalus for centuries.</p><p>Choice A is incorrect because &ldquo;for example&rdquo; illogically signals that the information about Arabic words entering Spanish exemplifies the Arabic-speaking history of Al-Andalus mentioned in the previous sentence. Instead, Arabic words entering Spanish is a consequence of that history. Choice B is incorrect because &ldquo;instead&rdquo; illogically signals that the information about Arabic words entering Spanish provides an alternative to the Arabic-speaking history of Al-Andalus mentioned in the previous sentence. The information about Arabic words entering Spanish is a consequence of that history. Choice C is incorrect because &ldquo;specifically&rdquo; illogically signals that the information about Arabic words entering Spanish provides specific details elaborating on the Arabic-speaking history of Al-Andalus mentioned in the previous sentence. Instead, Arabic words entering Spanish is a consequence of that history.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"b88dad9d","external_id":"075003df-5e06-4b3f-88b4-1a859b06ea0d","vaultid":null,"uId":"23394569-badf-41d1-aa3f-1cf3bdc7c017","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Al-Andalus, the historical region of the Iberian Peninsula that includes most of modern-day Spain, was ruled by various Arabic-speaking Muslim states between the eighth and fifteenth centuries. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> many Arabic words, such as &ldquo;alacr&aacute;n&rdquo;&mdash;meaning &ldquo;scorpion&rdquo;&mdash;made their way into the Spanish language.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"aded8720-0d42-4254-ae1d-84883db308e9","content":"<p>For example,</p>"},{"id":"4bce628d-c873-475a-bae6-a69aa823b0ce","content":"<p>Instead,</p>"},{"id":"2ed7b190-42eb-4b86-9c04-108931e2cadc","content":"<p>Specifically,</p>"},{"id":"061bfb10-cfe0-4d62-9edd-07afeacacc8f","content":"<p>Consequently,</p>"}],"keys":["061bfb10-cfe0-4d62-9edd-07afeacacc8f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;Consequently&rdquo; logically signals that the information in this sentence&mdash;that many Arabic words entered the Spanish language&mdash;is a result or consequence of the previous information about Arabic-speaking Muslim states ruling Al-Andalus for centuries.</p><p>Choice A is incorrect because &ldquo;for example&rdquo; illogically signals that the information about Arabic words entering Spanish exemplifies the Arabic-speaking history of Al-Andalus mentioned in the previous sentence. Instead, Arabic words entering Spanish is a consequence of that history. Choice B is incorrect because &ldquo;instead&rdquo; illogically signals that the information about Arabic words entering Spanish provides an alternative to the Arabic-speaking history of Al-Andalus mentioned in the previous sentence. The information about Arabic words entering Spanish is a consequence of that history. Choice C is incorrect because &ldquo;specifically&rdquo; illogically signals that the information about Arabic words entering Spanish provides specific details elaborating on the Arabic-speaking history of Al-Andalus mentioned in the previous sentence. Instead, Arabic words entering Spanish is a consequence of that history.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771167,"updateDate":1776362771167}$SATQ$::jsonb, 1776362771167, 1776362771167),
    ($SATQ$b8eec031$SATQ$, $SATQ$53e572cc-c894-48ae-af49-0a8c3262b1a6$SATQ$::uuid, $SATQ$fec5cc87-2cf7-42a7-948c-7e9ed59c9f4c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Researchers Helena Mihaljević-Brandt, Luc&iacute;a Santamar&iacute;a, and Marco Tullney report that while mathematicians may have traditionally worked alone, evidence points to a shift in the opposite direction. <span aria-hidden="true">______</span><span class="sr-only">blank</span> mathematicians are choosing to collaborate with their peers&mdash;a trend illustrated by a rise in the number of mathematics publications credited to multiple authors.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"97e95d67-c992-4c40-ab5f-6bbc95847a5c","content":"<p>Similarly,</p>"},{"id":"6b14100e-971f-46a8-a7ec-9d08cb0a2fbc","content":"<p>For this reason,</p>"},{"id":"3c2a2b03-8736-4944-80c0-c221e0f8895b","content":"<p>Furthermore,</p>"},{"id":"92d785a3-497d-4243-a3df-4d5dab226c37","content":"<p>Increasingly,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["92d785a3-497d-4243-a3df-4d5dab226c37"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;Increasingly&rdquo; logically signals that the claim in this sentence&mdash;that mathematicians are collaborating with their peers&mdash;marks a change relative to what was traditionally done. As the previous sentence explains, while mathematicians may have traditionally worked alone, evidence points to a shift in the opposite direction. The claim describes the shift: a rise in collaboration. </p><p>Choice A is incorrect because &ldquo;similarly&rdquo; illogically signals that the claim in this sentence is similar to, but separate from, the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift. Choice B is incorrect because &ldquo;for this reason&rdquo; illogically signals that the claim in this sentence is caused by the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift. Choice C is incorrect because &ldquo;furthermore&rdquo; illogically signals that the claim in this sentence is in addition to the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift. </p>$SATQ$, false, 0, $SATQ$OSP-211-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$8b2aa550-682c-4b28-a4f2-abcc881150a0$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"b8eec031","external_id":"53e572cc-c894-48ae-af49-0a8c3262b1a6","vaultid":"fec5cc87-2cf7-42a7-948c-7e9ed59c9f4c","uId":"b604cf28-c24a-4c46-bcc1-6e61315829a7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Researchers Helena Mihaljević-Brandt, Luc&iacute;a Santamar&iacute;a, and Marco Tullney report that while mathematicians may have traditionally worked alone, evidence points to a shift in the opposite direction. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> mathematicians are choosing to collaborate with their peers&mdash;a trend illustrated by a rise in the number of mathematics publications credited to multiple authors.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"97e95d67-c992-4c40-ab5f-6bbc95847a5c","content":"<p>Similarly,</p>"},{"id":"6b14100e-971f-46a8-a7ec-9d08cb0a2fbc","content":"<p>For this reason,</p>"},{"id":"3c2a2b03-8736-4944-80c0-c221e0f8895b","content":"<p>Furthermore,</p>"},{"id":"92d785a3-497d-4243-a3df-4d5dab226c37","content":"<p>Increasingly,</p>"}],"keys":["92d785a3-497d-4243-a3df-4d5dab226c37"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;Increasingly&rdquo; logically signals that the claim in this sentence&mdash;that mathematicians are collaborating with their peers&mdash;marks a change relative to what was traditionally done. As the previous sentence explains, while mathematicians may have traditionally worked alone, evidence points to a shift in the opposite direction. The claim describes the shift: a rise in collaboration. </p><p>Choice A is incorrect because &ldquo;similarly&rdquo; illogically signals that the claim in this sentence is similar to, but separate from, the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift. Choice B is incorrect because &ldquo;for this reason&rdquo; illogically signals that the claim in this sentence is caused by the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift. Choice C is incorrect because &ldquo;furthermore&rdquo; illogically signals that the claim in this sentence is in addition to the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift. </p>","parenttemplatename":"OSP-211-TRA","parenttemplateid":"","templateclusterid":"8b2aa550-682c-4b28-a4f2-abcc881150a0","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959327,"updateDate":1691007959327}$SATQ$::jsonb, 1691007959327, 1691007959327),
    ($SATQ$b98b8f64$SATQ$, $SATQ$b86b2793-d441-430f-a014-82f5bc9ba60b$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>1926: The US Congress gave the US Commerce Department authority to regulate safety standards in the fledgling commercial airline industry.</li>
<li>1938: Congress transferred this authority to a new independent government agency called the Civil Aeronautics Authority (<span data-ssml-say-as="characters">CAA</span>).</li>
<li>1958: Congress transferred authority from the <span data-ssml-say-as="characters">CAA</span> to the newly established Federal Aviation Administration (<span data-ssml-say-as="characters">FAA</span>).</li>
<li>The <span data-ssml-sub-alias="F A A&rsquo;s">FAA&rsquo;s</span> first administrator, Elwood <span data-ssml-sub-alias="R">R.</span> Quesada, updated safety standards and technologies for the era of commercial jets.</li>
<li>The <span data-ssml-say-as="characters">FAA</span> remains the regulatory authority for airline safety.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to specify the order in which different government entities were given the authority to regulate airline safety in the US. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"4c5230bf-4a4a-418b-b79f-a405b5b8c986","content":"<p>The <span data-ssml-say-as=\"characters\">CAA</span> had the authority to regulate safety for US airlines from 1938 until 1958, at which point authority was transferred to the US Commerce Department by Elwood <span data-ssml-sub-alias=\"R\">R.</span> Quesada.</p>"},{"id":"16442bcc-8b82-4615-b123-1bc4f3d1a800","content":"<p>The <span data-ssml-say-as=\"characters\">FAA</span>, <span data-ssml-say-as=\"characters\">CAA</span>, and the US Commerce Department all had the authority to regulate US airline safety, but they possessed this authority at different times.</p>"},{"id":"55f1f75d-4458-4e2c-bc0c-7c8afd2cc7bf","content":"<p>The <span data-ssml-say-as=\"characters\">FAA</span> has regulated airline safety since it was established by the US Congress in 1958.</p>"},{"id":"0cddb63e-7f0c-4121-9ad2-1c727cf3d654","content":"<p>The authority to regulate US airline safety transferred from the US Commerce Department to the <span data-ssml-say-as=\"characters\">CAA</span> in 1938, then from the <span data-ssml-say-as=\"characters\">CAA</span> to the <span data-ssml-say-as=\"characters\">FAA</span> in 1958.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["0cddb63e-7f0c-4121-9ad2-1c727cf3d654"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence specifies the order in which different government entities were given the authority to regulate US airline safety, noting that this role shifted from the US Commerce Department to the CAA in 1938, then from the CAA to the FAA in 1958.</p><p>Choice A is incorrect because it misrepresents information from the notes. The authority to regulate airline safety was transferred to the FAA in 1958, not to the US Commerce Department. Moreover, the sentence misrepresents Quesada&rsquo;s role as described in the notes. Choice B is incorrect. While the sentence mentions that all three entities had the authority to regulate US airline safety at different times, it doesn&rsquo;t specify the chronological order in which they held that authority. Choice C is incorrect. The sentence only mentions when the FAA began regulating US airline safety; it doesn&rsquo;t specify the order in which different government entities held that authority.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"b98b8f64","external_id":"b86b2793-d441-430f-a014-82f5bc9ba60b","vaultid":null,"uId":"98c18d42-9151-4677-800e-322d0045ab7a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>1926: The US Congress gave the US Commerce Department authority to regulate safety standards in the fledgling commercial airline industry.</li>\n<li>1938: Congress transferred this authority to a new independent government agency called the Civil Aeronautics Authority (<span data-ssml-say-as=\"characters\">CAA</span>).</li>\n<li>1958: Congress transferred authority from the <span data-ssml-say-as=\"characters\">CAA</span> to the newly established Federal Aviation Administration (<span data-ssml-say-as=\"characters\">FAA</span>).</li>\n<li>The <span data-ssml-sub-alias=\"F A A&rsquo;s\">FAA&rsquo;s</span> first administrator, Elwood <span data-ssml-sub-alias=\"R\">R.</span> Quesada, updated safety standards and technologies for the era of commercial jets.</li>\n<li>The <span data-ssml-say-as=\"characters\">FAA</span> remains the regulatory authority for airline safety.</li>\n</ul>","stem":"<p>The student wants to specify the order in which different government entities were given the authority to regulate airline safety in the US. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"4c5230bf-4a4a-418b-b79f-a405b5b8c986","content":"<p>The <span data-ssml-say-as=\"characters\">CAA</span> had the authority to regulate safety for US airlines from 1938 until 1958, at which point authority was transferred to the US Commerce Department by Elwood <span data-ssml-sub-alias=\"R\">R.</span> Quesada.</p>"},{"id":"16442bcc-8b82-4615-b123-1bc4f3d1a800","content":"<p>The <span data-ssml-say-as=\"characters\">FAA</span>, <span data-ssml-say-as=\"characters\">CAA</span>, and the US Commerce Department all had the authority to regulate US airline safety, but they possessed this authority at different times.</p>"},{"id":"55f1f75d-4458-4e2c-bc0c-7c8afd2cc7bf","content":"<p>The <span data-ssml-say-as=\"characters\">FAA</span> has regulated airline safety since it was established by the US Congress in 1958.</p>"},{"id":"0cddb63e-7f0c-4121-9ad2-1c727cf3d654","content":"<p>The authority to regulate US airline safety transferred from the US Commerce Department to the <span data-ssml-say-as=\"characters\">CAA</span> in 1938, then from the <span data-ssml-say-as=\"characters\">CAA</span> to the <span data-ssml-say-as=\"characters\">FAA</span> in 1958.</p>"}],"keys":["0cddb63e-7f0c-4121-9ad2-1c727cf3d654"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence specifies the order in which different government entities were given the authority to regulate US airline safety, noting that this role shifted from the US Commerce Department to the CAA in 1938, then from the CAA to the FAA in 1958.</p><p>Choice A is incorrect because it misrepresents information from the notes. The authority to regulate airline safety was transferred to the FAA in 1958, not to the US Commerce Department. Moreover, the sentence misrepresents Quesada&rsquo;s role as described in the notes. Choice B is incorrect. While the sentence mentions that all three entities had the authority to regulate US airline safety at different times, it doesn&rsquo;t specify the chronological order in which they held that authority. Choice C is incorrect. The sentence only mentions when the FAA began regulating US airline safety; it doesn&rsquo;t specify the order in which different government entities held that authority.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771170,"updateDate":1776362771170}$SATQ$::jsonb, 1776362771170, 1776362771170),
    ($SATQ$ba263620$SATQ$, $SATQ$e7bfc1b3-da00-4de5-801a-ff2b68ea897f$SATQ$::uuid, $SATQ$3426f0c9-bbcc-4a16-bce8-fb39aa89b92c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>In 1897, African American inventor Andrew Beard invented an automatic coupler.</li>
<li>It improved on the existing design of train car couplers.</li>
<li>It made the job of connecting train cars safer.</li>
<li>In 1938, African American inventor Frederick Jones invented a mobile refrigeration system.</li>
<li>It improved on the existing design of food transport trucks.</li>
<li>It enabled trucks to carry perishable foods farther.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a similarity between Beard&rsquo;s invention and Jones&rsquo;s invention. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"cc67e4d0-ae82-4428-9564-20ee038fd101","content":"<p>Beard&rsquo;s automatic coupler and Jones&rsquo;s mobile refrigeration system both improved on existing designs.</p>"},{"id":"7891851b-872a-46ca-a1cf-8cc1228ba87f","content":"<p>In 1897, Beard invented an automatic coupler, which made the job of connecting train cars safer.</p>"},{"id":"24ed0a42-ec19-431b-a562-78c6c808b4d9","content":"<p>Beard&rsquo;s invention made the job of connecting train cars safer, whereas Jones&rsquo;s invention enabled food transport trucks to carry perishables farther.&nbsp;</p>"},{"id":"b36cfc56-4916-4816-afd0-539b3151e520","content":"<p>Jones&rsquo;s mobile refrigeration system, which he invented in 1938, made it possible for food transport trucks to carry perishable foods farther.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["cc67e4d0-ae82-4428-9564-20ee038fd101"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. It compares Beard&rsquo;s and Jones&rsquo;s inventions to one another, and emphasizes what they have in common. </p><p>Choice B is incorrect. This choice doesn&rsquo;t emphasize a similarity. It only mentions Beard&rsquo;s invention. It doesn&rsquo;t compare it to Jones&rsquo;s invention. Choice C is incorrect. This choice doesn&rsquo;t emphasize a similarity between the two inventions. Instead, it emphasizes a difference. Choice D is incorrect. This choice doesn&rsquo;t emphasize a similarity. It only mentions Jones&rsquo;s invention. It doesn&rsquo;t compare it to Beard&rsquo;s invention. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-E002$SATQ$, $SATQ$$SATQ$, $SATQ$179c4b2b-8b63-40f2-bc56-fcc60bfb94ca$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ba263620","external_id":"e7bfc1b3-da00-4de5-801a-ff2b68ea897f","vaultid":"3426f0c9-bbcc-4a16-bce8-fb39aa89b92c","uId":"c42ae0c4-4bd8-4662-b1cb-27bc0ffe1e89","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>In 1897, African American inventor Andrew Beard invented an automatic coupler.</li>\n<li>It improved on the existing design of train car couplers.</li>\n<li>It made the job of connecting train cars safer.</li>\n<li>In 1938, African American inventor Frederick Jones invented a mobile refrigeration system.</li>\n<li>It improved on the existing design of food transport trucks.</li>\n<li>It enabled trucks to carry perishable foods farther.</li>\n</ul>","stem":"<p>The student wants to emphasize a similarity between Beard&rsquo;s invention and Jones&rsquo;s invention. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"cc67e4d0-ae82-4428-9564-20ee038fd101","content":"<p>Beard&rsquo;s automatic coupler and Jones&rsquo;s mobile refrigeration system both improved on existing designs.</p>"},{"id":"7891851b-872a-46ca-a1cf-8cc1228ba87f","content":"<p>In 1897, Beard invented an automatic coupler, which made the job of connecting train cars safer.</p>"},{"id":"24ed0a42-ec19-431b-a562-78c6c808b4d9","content":"<p>Beard&rsquo;s invention made the job of connecting train cars safer, whereas Jones&rsquo;s invention enabled food transport trucks to carry perishables farther.&nbsp;</p>"},{"id":"b36cfc56-4916-4816-afd0-539b3151e520","content":"<p>Jones&rsquo;s mobile refrigeration system, which he invented in 1938, made it possible for food transport trucks to carry perishable foods farther.</p>"}],"keys":["cc67e4d0-ae82-4428-9564-20ee038fd101"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. It compares Beard&rsquo;s and Jones&rsquo;s inventions to one another, and emphasizes what they have in common. </p><p>Choice B is incorrect. This choice doesn&rsquo;t emphasize a similarity. It only mentions Beard&rsquo;s invention. It doesn&rsquo;t compare it to Jones&rsquo;s invention. Choice C is incorrect. This choice doesn&rsquo;t emphasize a similarity between the two inventions. Instead, it emphasizes a difference. Choice D is incorrect. This choice doesn&rsquo;t emphasize a similarity. It only mentions Jones&rsquo;s invention. It doesn&rsquo;t compare it to Beard&rsquo;s invention. </p>","parenttemplatename":"OSP-KA-SYN-E002","parenttemplateid":"","templateclusterid":"179c4b2b-8b63-40f2-bc56-fcc60bfb94ca","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959371,"updateDate":1691007959371}$SATQ$::jsonb, 1691007959371, 1691007959371),
    ($SATQ$bb275f0d$SATQ$, $SATQ$ac00b01b-d2bb-46df-8b1e-5454ee83e79a$SATQ$::uuid, $SATQ$5a8bbe40-7677-4104-bd7d-c0057de25c4d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Cities tend to have a wide range of flowering vegetation in parks, yards, and gardens.</li>
<li>This vegetation provides a varied diet for honeybees, strengthening bees&rsquo; immune systems.</li>
<li>On average, 62.5 percent of bees in an urban area will survive a harsh winter.</li>
<li>Rural areas are often dominated by monoculture crops such as corn or wheat.</li>
<li>On average, only 40 percent of honeybees in a rural area will survive a harsh winter.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to make and support a generalization about honeybees.&nbsp;Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"e1521cb6-3c4c-416a-a747-1f2e3785b2b3","content":"<p>Cities tend to have a wider range of flowering vegetation than do rural areas, which are often dominated by monoculture crops.</p>"},{"id":"bbc3b407-ae2c-407c-a4d7-3e3cb4228689","content":"<p>In urban areas, over 60 percent of honeybees, on average, will survive a harsh winter, whereas in rural areas, only 40 percent will.&nbsp;</p>"},{"id":"cee23bd1-a82a-4eae-a762-de6f5716989d","content":"<p>The strength of honeybees&rsquo; immune systems depends on what the bees eat, and a varied diet is more available to bees in an urban area than to those in a rural area.</p>"},{"id":"e3f08f6a-3768-49c7-944f-f893ba5f2691","content":"<p>Honeybees are more likely to thrive in cities than in rural areas because the varied diet available in urban areas strengthens the bees&rsquo; immune systems.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["e3f08f6a-3768-49c7-944f-f893ba5f2691"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because the sentence makes and supports a generalization about honeybees. It claims that honeybees living in urban areas are more likely to thrive than rural bees, and it supports the claim with information about the effect of a varied diet on urban bees&rsquo; immune systems.&nbsp;</p><p>Choice A is incorrect. While the sentence makes a generalization, it doesn&rsquo;t mention honeybees.&nbsp;Choice B is incorrect. While the sentence provides data about honeybee survival, it doesn&rsquo;t make a generalization about honeybees based on this information. Choice C is incorrect. While the sentence makes a generalization about honeybees&rsquo; diets and immune systems, it doesn&rsquo;t provide adequate support for this generalization. </p>$SATQ$, false, 0, $SATQ$OSP-756-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$65b7aa8f-be4c-4bde-8514-4793f07b2cf2$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"bb275f0d","external_id":"ac00b01b-d2bb-46df-8b1e-5454ee83e79a","vaultid":"5a8bbe40-7677-4104-bd7d-c0057de25c4d","uId":"2eafa12a-c38b-4abf-9cfd-e8db78628fa0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Cities tend to have a wide range of flowering vegetation in parks, yards, and gardens.</li>\n<li>This vegetation provides a varied diet for honeybees, strengthening bees&rsquo; immune systems.</li>\n<li>On average, 62.5 percent of bees in an urban area will survive a harsh winter.</li>\n<li>Rural areas are often dominated by monoculture crops such as corn or wheat.</li>\n<li>On average, only 40 percent of honeybees in a rural area will survive a harsh winter.</li>\n</ul>","stem":"<p>The student wants to make and support a generalization about honeybees.&nbsp;Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"e1521cb6-3c4c-416a-a747-1f2e3785b2b3","content":"<p>Cities tend to have a wider range of flowering vegetation than do rural areas, which are often dominated by monoculture crops.</p>"},{"id":"bbc3b407-ae2c-407c-a4d7-3e3cb4228689","content":"<p>In urban areas, over 60 percent of honeybees, on average, will survive a harsh winter, whereas in rural areas, only 40 percent will.&nbsp;</p>"},{"id":"cee23bd1-a82a-4eae-a762-de6f5716989d","content":"<p>The strength of honeybees&rsquo; immune systems depends on what the bees eat, and a varied diet is more available to bees in an urban area than to those in a rural area.</p>"},{"id":"e3f08f6a-3768-49c7-944f-f893ba5f2691","content":"<p>Honeybees are more likely to thrive in cities than in rural areas because the varied diet available in urban areas strengthens the bees&rsquo; immune systems.</p>"}],"keys":["e3f08f6a-3768-49c7-944f-f893ba5f2691"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because the sentence makes and supports a generalization about honeybees. It claims that honeybees living in urban areas are more likely to thrive than rural bees, and it supports the claim with information about the effect of a varied diet on urban bees&rsquo; immune systems.&nbsp;</p><p>Choice A is incorrect. While the sentence makes a generalization, it doesn&rsquo;t mention honeybees.&nbsp;Choice B is incorrect. While the sentence provides data about honeybee survival, it doesn&rsquo;t make a generalization about honeybees based on this information. Choice C is incorrect. While the sentence makes a generalization about honeybees&rsquo; diets and immune systems, it doesn&rsquo;t provide adequate support for this generalization. </p>","parenttemplatename":"OSP-756-SYN","parenttemplateid":"","templateclusterid":"65b7aa8f-be4c-4bde-8514-4793f07b2cf2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959351,"updateDate":1691007959351}$SATQ$::jsonb, 1691007959351, 1691007959351),
    ($SATQ$bb43fc3c$SATQ$, $SATQ$4df3e839-dce7-4e36-a223-bdb49e614702$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p><p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Pedestrian malls are outdoor streets in a city or town where vehicle traffic is prohibited.</li>
<li>Many pedestrian malls were built in the 19th and 20th centuries in Europe and Asia.</li>
<li>Qianmen Dajie is a famous pedestrian mall in Beijing.</li>
<li>It has existed since the Ming dynasty (1368&ndash;1644 CE).</li>
<li>Rue Mouffetard is a famous pedestrian mall in Paris.</li>
<li>It has existed since the mid-Roman Empire (117&ndash;235 CE).</li>
</ul></p>$SATQ$, $SATQ$<p>The student wants to emphasize a similarity between the ages of the malls. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"03e59bcf-5614-4c65-94ef-2ef2a0ed362e","content":"<p>The Qianmen Dajie pedestrian mall has roots as far back as the Ming dynasty; likewise, Rue Mouffetard has existed for centuries.</p>"},{"id":"7bc36867-d213-40d4-bdc7-50f60a18a68b","content":"<p>Both Qianmen Dajie and Rue Mouffetard are famous pedestrian malls, the former in Beijing and the latter in Paris.</p>"},{"id":"e59a6eb4-dfb8-4e37-b1b2-376c9329468e","content":"<p>Qianmen Dajie and Rue Mouffetard are pedestrian malls, outdoor streets closed to vehicle traffic.</p>"},{"id":"9a9efc2f-329b-41e0-a16e-6bec55b88e9a","content":"<p>Qianmen Dajie and Rue Mouffetard are examples of pedestrian malls, which proliferated in Europe in the 19th and 20th centuries.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["03e59bcf-5614-4c65-94ef-2ef2a0ed362e"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence emphasizes a similarity between the ages of the two pedestrian malls, noting that both are relatively old&mdash;Qianmen Dajie has roots that go back hundreds of years and Rue Mouffetard has existed for centuries.</p><p>Choice B is incorrect. The sentence emphasizes that both locations are famous pedestrian malls and notes that they are in different locations; it doesn&rsquo;t emphasize a similarity in their ages. Choice C is incorrect. While the sentence emphasizes that both locations are pedestrian malls, it doesn&rsquo;t emphasize a similarity in their ages. Choice D is incorrect. The sentence explains that Qianmen Dajie and Rue Mouffetard are examples of pedestrian malls and gives information about pedestrian malls in general; it doesn&rsquo;t emphasize a similarity in the ages of these two malls specifically.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"bb43fc3c","external_id":"4df3e839-dce7-4e36-a223-bdb49e614702","vaultid":null,"uId":"de568950-4f0d-4f80-9075-946360f88d66","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p><p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Pedestrian malls are outdoor streets in a city or town where vehicle traffic is prohibited.</li>\n<li>Many pedestrian malls were built in the 19th and 20th centuries in Europe and Asia.</li>\n<li>Qianmen Dajie is a famous pedestrian mall in Beijing.</li>\n<li>It has existed since the Ming dynasty (1368&ndash;1644 CE).</li>\n<li>Rue Mouffetard is a famous pedestrian mall in Paris.</li>\n<li>It has existed since the mid-Roman Empire (117&ndash;235 CE).</li>\n</ul></p>","stem":"<p>The student wants to emphasize a similarity between the ages of the malls. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"03e59bcf-5614-4c65-94ef-2ef2a0ed362e","content":"<p>The Qianmen Dajie pedestrian mall has roots as far back as the Ming dynasty; likewise, Rue Mouffetard has existed for centuries.</p>"},{"id":"7bc36867-d213-40d4-bdc7-50f60a18a68b","content":"<p>Both Qianmen Dajie and Rue Mouffetard are famous pedestrian malls, the former in Beijing and the latter in Paris.</p>"},{"id":"e59a6eb4-dfb8-4e37-b1b2-376c9329468e","content":"<p>Qianmen Dajie and Rue Mouffetard are pedestrian malls, outdoor streets closed to vehicle traffic.</p>"},{"id":"9a9efc2f-329b-41e0-a16e-6bec55b88e9a","content":"<p>Qianmen Dajie and Rue Mouffetard are examples of pedestrian malls, which proliferated in Europe in the 19th and 20th centuries.</p>"}],"keys":["03e59bcf-5614-4c65-94ef-2ef2a0ed362e"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence emphasizes a similarity between the ages of the two pedestrian malls, noting that both are relatively old&mdash;Qianmen Dajie has roots that go back hundreds of years and Rue Mouffetard has existed for centuries.</p><p>Choice B is incorrect. The sentence emphasizes that both locations are famous pedestrian malls and notes that they are in different locations; it doesn&rsquo;t emphasize a similarity in their ages. Choice C is incorrect. While the sentence emphasizes that both locations are pedestrian malls, it doesn&rsquo;t emphasize a similarity in their ages. Choice D is incorrect. The sentence explains that Qianmen Dajie and Rue Mouffetard are examples of pedestrian malls and gives information about pedestrian malls in general; it doesn&rsquo;t emphasize a similarity in the ages of these two malls specifically.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$bc56170b$SATQ$, $SATQ$1659cb41-9b8d-42c6-83cb-67b755124e92$SATQ$::uuid, $SATQ$9ef0cb7c-f450-4e9d-8075-3cbe46105ed1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Most, but not all, of the Moon&rsquo;s oxygen comes from the Sun, via solar wind.</li>
<li>Cosmochemist Kentaro Terada from Osaka University wondered if some of the unaccounted-for oxygen could be coming from Earth.</li>
<li>In 2008, he analyzed data from the Japanese satellite Kaguya.</li>
<li>Kaguya gathered data about gases and particles it encountered while orbiting the Moon.</li>
<li>Based on the Kaguya data, Terada confirmed his suspicion that Earth is sending oxygen to the Moon.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize the aim of the research study. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"9fe7d6e6-de6b-4cdf-b9e4-04205ace7f29","content":"<p>As it orbited the Moon, the Kaguya satellite collected data that was later analyzed by cosmochemist Kentaro Terada.</p>"},{"id":"11155b3e-044c-41f1-aba8-a11ac8843ba7","content":"<p>Before 2008, Kentaro Terada wondered if the Moon was receiving some of its oxygen from Earth.</p>"},{"id":"0888a3f9-369c-454f-8875-54c30c0c9835","content":"<p>Cosmochemist Kentaro Terada set out to determine whether some of the Moon&rsquo;s oxygen was coming from Earth.</p>"},{"id":"c46a0cb4-e715-422c-95b4-f1ead3eb3bfa","content":"<p>Kentaro Terada&rsquo;s study determined that Earth is sending a small amount of oxygen to the Moon.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["0888a3f9-369c-454f-8875-54c30c0c9835"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence emphasizes the aim, or goal, of the research study, noting what Terada set out to do: determine whether some of the Moon&rsquo;s oxygen was coming from Earth. </p><p>Choice A is incorrect. The sentence focuses on how the Kaguya satellite collected data; it doesn&rsquo;t emphasize the aim of the research study. Choice B is incorrect. While the sentence mentions what Terada was curious about before conducting the research study, it doesn&rsquo;t emphasize his study&rsquo;s aim. Choice D is incorrect. The sentence presents the research study&rsquo;s conclusion; it doesn&rsquo;t emphasize the study&rsquo;s aim. </p>$SATQ$, false, 0, $SATQ$OSP-741-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$023b893a-1153-4dc5-9c9a-f56e7d8bd3e9$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"bc56170b","external_id":"1659cb41-9b8d-42c6-83cb-67b755124e92","vaultid":"9ef0cb7c-f450-4e9d-8075-3cbe46105ed1","uId":"e2e21f56-df4f-4695-9136-8ba8879bd9d7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Most, but not all, of the Moon&rsquo;s oxygen comes from the Sun, via solar wind.</li>\n<li>Cosmochemist Kentaro Terada from Osaka University wondered if some of the unaccounted-for oxygen could be coming from Earth.</li>\n<li>In 2008, he analyzed data from the Japanese satellite Kaguya.</li>\n<li>Kaguya gathered data about gases and particles it encountered while orbiting the Moon.</li>\n<li>Based on the Kaguya data, Terada confirmed his suspicion that Earth is sending oxygen to the Moon.</li>\n</ul>","stem":"<p>The student wants to emphasize the aim of the research study. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"9fe7d6e6-de6b-4cdf-b9e4-04205ace7f29","content":"<p>As it orbited the Moon, the Kaguya satellite collected data that was later analyzed by cosmochemist Kentaro Terada.</p>"},{"id":"11155b3e-044c-41f1-aba8-a11ac8843ba7","content":"<p>Before 2008, Kentaro Terada wondered if the Moon was receiving some of its oxygen from Earth.</p>"},{"id":"0888a3f9-369c-454f-8875-54c30c0c9835","content":"<p>Cosmochemist Kentaro Terada set out to determine whether some of the Moon&rsquo;s oxygen was coming from Earth.</p>"},{"id":"c46a0cb4-e715-422c-95b4-f1ead3eb3bfa","content":"<p>Kentaro Terada&rsquo;s study determined that Earth is sending a small amount of oxygen to the Moon.</p>"}],"keys":["0888a3f9-369c-454f-8875-54c30c0c9835"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence emphasizes the aim, or goal, of the research study, noting what Terada set out to do: determine whether some of the Moon&rsquo;s oxygen was coming from Earth. </p><p>Choice A is incorrect. The sentence focuses on how the Kaguya satellite collected data; it doesn&rsquo;t emphasize the aim of the research study. Choice B is incorrect. While the sentence mentions what Terada was curious about before conducting the research study, it doesn&rsquo;t emphasize his study&rsquo;s aim. Choice D is incorrect. The sentence presents the research study&rsquo;s conclusion; it doesn&rsquo;t emphasize the study&rsquo;s aim. </p>","parenttemplatename":"OSP-741-SYN","parenttemplateid":"","templateclusterid":"023b893a-1153-4dc5-9c9a-f56e7d8bd3e9","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959350,"updateDate":1691007959350}$SATQ$::jsonb, 1691007959350, 1691007959350),
    ($SATQ$bc930940$SATQ$, $SATQ$ec62edc1-d6f2-4d3b-8de3-645b2da14e65$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Chiura Obata was a Japanese American artist who lived in California.</li>
<li><em>Yosemite Falls</em> is a notable painting by Obata. &nbsp;</li>
<li>It uses a Japanese method of black ink painting called sumi-e.</li>
<li>This painting was completed in 1930.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to indicate the year <em>Yosemite Falls</em> was completed.&nbsp; Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"67506613-0daf-401c-a613-5572531ea710","content":"<p>While living in California, Obata created black ink paintings.&nbsp;</p>"},{"id":"022cfdb5-8f8c-4ae3-a4c4-88db7ae93436","content":"<p>Obata, a Japanese American artist, created a notable painting.</p>"},{"id":"563ddf3a-def4-4671-9bce-aa73961adfbe","content":"<p><em>Yosemite Falls</em> was completed in 1930.</p>"},{"id":"263bb419-7fc9-4e5f-85b1-b48fc72f6a35","content":"<p>Obata used a Japanese painting method called sumi-e.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["563ddf3a-def4-4671-9bce-aa73961adfbe"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence indicates the year <em>Yosemite Falls</em> was completed, stating that it was completed in 1930.</p><p>Choice A is incorrect. The sentence indicates where Obata created black ink paintings; it doesn&rsquo;t indicate when the painting was completed. Choice B is incorrect. While the sentence identifies Obata as an artist who created a notable painting, it doesn&rsquo;t indicate when that painting was completed. Choice D is incorrect. The sentence identifies the method Obata used; it doesn&rsquo;t indicate when the painting was completed.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"bc930940","external_id":"ec62edc1-d6f2-4d3b-8de3-645b2da14e65","vaultid":null,"uId":"3190f6e1-1073-43d8-abf5-c25f429d7074","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Chiura Obata was a Japanese American artist who lived in California.</li>\n<li><em>Yosemite Falls</em> is a notable painting by Obata. &nbsp;</li>\n<li>It uses a Japanese method of black ink painting called sumi-e.</li>\n<li>This painting was completed in 1930.</li>\n</ul>","stem":"<p>The student wants to indicate the year <em>Yosemite Falls</em> was completed.&nbsp; Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"67506613-0daf-401c-a613-5572531ea710","content":"<p>While living in California, Obata created black ink paintings.&nbsp;</p>"},{"id":"022cfdb5-8f8c-4ae3-a4c4-88db7ae93436","content":"<p>Obata, a Japanese American artist, created a notable painting.</p>"},{"id":"563ddf3a-def4-4671-9bce-aa73961adfbe","content":"<p><em>Yosemite Falls</em> was completed in 1930.</p>"},{"id":"263bb419-7fc9-4e5f-85b1-b48fc72f6a35","content":"<p>Obata used a Japanese painting method called sumi-e.</p>"}],"keys":["563ddf3a-def4-4671-9bce-aa73961adfbe"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence indicates the year <em>Yosemite Falls</em> was completed, stating that it was completed in 1930.</p><p>Choice A is incorrect. The sentence indicates where Obata created black ink paintings; it doesn&rsquo;t indicate when the painting was completed. Choice B is incorrect. While the sentence identifies Obata as an artist who created a notable painting, it doesn&rsquo;t indicate when that painting was completed. Choice D is incorrect. The sentence identifies the method Obata used; it doesn&rsquo;t indicate when the painting was completed.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669214,"updateDate":1743430669214}$SATQ$::jsonb, 1743430669214, 1743430669214),
    ($SATQ$bce57278$SATQ$, $SATQ$c6f5eb0a-6a1b-46ad-9236-c2c96c824762$SATQ$::uuid, $SATQ$8176d6a4-300c-481a-8a10-d8e022841f01$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Some US reformers sought to improve society in the 1800s by building utopias.</li>
<li>A utopia is a community intended to represent a perfect society based on a specific set of principles.</li>
<li>One such community was Brook Farm near Boston, Massachusetts.</li>
<li>It was founded in 1841 by writer George Ripley.</li>
<li>Ripley wrote in a letter that his goal for Brook Farm was &ldquo;to guarantee the highest mental freedom, by providing all with labor, adapted to their tastes and talents, and securing to them the fruits of their industry.&rdquo;</li>
</ul>$SATQ$, $SATQ$<p>The student wants to explain the goal of Brook Farm using a quotation from George Ripley. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"f2c02501-0358-4a9f-88db-e9a522a6b433","content":"<p>In a letter, writer George Ripley explained his goal to &ldquo;guarantee the highest mental freedom.&rdquo;</p>"},{"id":"b61458f6-8abd-4d75-8040-e6f3d4729205","content":"<p>Utopias, such as Brook Farm, founded by George Ripley in 1841, were based on a specific set of principles intended to create a perfect society.</p>"},{"id":"b8588c3f-fdd5-4a6b-873a-15e5d8970f7f","content":"<p>Founded by George Ripley near Boston, Massachusetts, Brook Farm was part of a trend in the 1800s, when reformers in the United States built utopias.</p>"},{"id":"5b014b89-222e-41a9-96d2-85fa90ea531e","content":"<p>Established in 1841, Brook Farm was a utopian community created to &ldquo;guarantee the highest mental freedom, by providing all with labor... [and] the fruits of their industry,&rdquo; according to founder George Ripley.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["5b014b89-222e-41a9-96d2-85fa90ea531e"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. This choice explains the goal of Brook Farm&mdash;to provide mental freedom to all by engaging individuals in labor suited to their interests&mdash;using a quotation from George Ripley. </p><p>Choice A is incorrect. This choice only mentions part of Ripley&rsquo;s goal, and it doesn&rsquo;t mention Brook Farm at all. Choice B is incorrect. This choice defines what a utopia is but doesn&rsquo;t use Ripley&rsquo;s words to describe his vision for Brook Farm. Choice C is incorrect. This choice provides some background information about Brook Farm, but it doesn&rsquo;t explain its goals or include Ripley&rsquo;s words. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-M008$SATQ$, $SATQ$$SATQ$, $SATQ$aa2bd269-832f-464a-b699-f63f56a65c21$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"bce57278","external_id":"c6f5eb0a-6a1b-46ad-9236-c2c96c824762","vaultid":"8176d6a4-300c-481a-8a10-d8e022841f01","uId":"6ecb37b7-35dd-4cbf-b1ee-466e44496a14","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Some US reformers sought to improve society in the 1800s by building utopias.</li>\n<li>A utopia is a community intended to represent a perfect society based on a specific set of principles.</li>\n<li>One such community was Brook Farm near Boston, Massachusetts.</li>\n<li>It was founded in 1841 by writer George Ripley.</li>\n<li>Ripley wrote in a letter that his goal for Brook Farm was &ldquo;to guarantee the highest mental freedom, by providing all with labor, adapted to their tastes and talents, and securing to them the fruits of their industry.&rdquo;</li>\n</ul>","stem":"<p>The student wants to explain the goal of Brook Farm using a quotation from George Ripley. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"f2c02501-0358-4a9f-88db-e9a522a6b433","content":"<p>In a letter, writer George Ripley explained his goal to &ldquo;guarantee the highest mental freedom.&rdquo;</p>"},{"id":"b61458f6-8abd-4d75-8040-e6f3d4729205","content":"<p>Utopias, such as Brook Farm, founded by George Ripley in 1841, were based on a specific set of principles intended to create a perfect society.</p>"},{"id":"b8588c3f-fdd5-4a6b-873a-15e5d8970f7f","content":"<p>Founded by George Ripley near Boston, Massachusetts, Brook Farm was part of a trend in the 1800s, when reformers in the United States built utopias.</p>"},{"id":"5b014b89-222e-41a9-96d2-85fa90ea531e","content":"<p>Established in 1841, Brook Farm was a utopian community created to &ldquo;guarantee the highest mental freedom, by providing all with labor... [and] the fruits of their industry,&rdquo; according to founder George Ripley.</p>"}],"keys":["5b014b89-222e-41a9-96d2-85fa90ea531e"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. This choice explains the goal of Brook Farm&mdash;to provide mental freedom to all by engaging individuals in labor suited to their interests&mdash;using a quotation from George Ripley. </p><p>Choice A is incorrect. This choice only mentions part of Ripley&rsquo;s goal, and it doesn&rsquo;t mention Brook Farm at all. Choice B is incorrect. This choice defines what a utopia is but doesn&rsquo;t use Ripley&rsquo;s words to describe his vision for Brook Farm. Choice C is incorrect. This choice provides some background information about Brook Farm, but it doesn&rsquo;t explain its goals or include Ripley&rsquo;s words. </p>","parenttemplatename":"OSP-KA-SYN-M008","parenttemplateid":"","templateclusterid":"aa2bd269-832f-464a-b699-f63f56a65c21","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$be44fea0$SATQ$, $SATQ$38da0806-db4c-4d38-a6fd-65fd8d2824fc$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While studying jorō spiders, a large species originally from East Asia, University of Georgia researchers wondered if the spiders&rsquo; rapid spread throughout the southeastern US was a result of aggressive behavior. <span aria-hidden="true">______</span><span class="sr-only">blank</span> they discovered that jorō spiders are gentle giants who react to even minor disturbances by &ldquo;freezing&rdquo; in place for an hour or more.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"d6448bf1-8355-4f38-9d61-3ba38a85e99b","content":"<p>Therefore,</p>"},{"id":"a7250a5d-9c63-4b67-930e-7befd5065b6c","content":"<p>Instead,</p>"},{"id":"22556136-0c16-46fe-9943-d70038413ba1","content":"<p>For example,</p>"},{"id":"b57c5656-8537-4a61-a4f9-14209b5faceb","content":"<p>In other words,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a7250a5d-9c63-4b67-930e-7befd5065b6c"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. &ldquo;Instead&rdquo; logically signals that the information about the researchers&rsquo; discovery in this sentence&mdash;that jorō spiders are gentle giants who &ldquo;freeze&rdquo; in place when disturbed&mdash;contradicts their initial hypothesis about the spiders&rsquo; aggressiveness described in the previous sentence.</p><p>Choice A is incorrect because &ldquo;therefore&rdquo; illogically signals that the discovery about jorō spiders&rsquo; gentleness is a result of the initial hypothesis about their aggressive behavior. Instead, the sentence presents information that contradicts the initial hypothesis. Choice C is incorrect because &ldquo;for example&rdquo; illogically signals that the discovery about jorō spiders&rsquo; gentleness exemplifies the initial hypothesis about their aggressive behavior. Instead, the sentence presents information that contradicts the initial hypothesis. Choice D is incorrect because &ldquo;in other words&rdquo; illogically signals that the discovery about jorō spiders&rsquo; gentleness is merely restating or rephrasing the initial hypothesis about their aggressive behavior. Instead, the sentence presents information that contradicts the initial hypothesis.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"be44fea0","external_id":"38da0806-db4c-4d38-a6fd-65fd8d2824fc","vaultid":null,"uId":"0923fdc2-fd62-4cf3-a152-322dd690580a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While studying jorō spiders, a large species originally from East Asia, University of Georgia researchers wondered if the spiders&rsquo; rapid spread throughout the southeastern US was a result of aggressive behavior. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> they discovered that jorō spiders are gentle giants who react to even minor disturbances by &ldquo;freezing&rdquo; in place for an hour or more.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"d6448bf1-8355-4f38-9d61-3ba38a85e99b","content":"<p>Therefore,</p>"},{"id":"a7250a5d-9c63-4b67-930e-7befd5065b6c","content":"<p>Instead,</p>"},{"id":"22556136-0c16-46fe-9943-d70038413ba1","content":"<p>For example,</p>"},{"id":"b57c5656-8537-4a61-a4f9-14209b5faceb","content":"<p>In other words,</p>"}],"keys":["a7250a5d-9c63-4b67-930e-7befd5065b6c"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. &ldquo;Instead&rdquo; logically signals that the information about the researchers&rsquo; discovery in this sentence&mdash;that jorō spiders are gentle giants who &ldquo;freeze&rdquo; in place when disturbed&mdash;contradicts their initial hypothesis about the spiders&rsquo; aggressiveness described in the previous sentence.</p><p>Choice A is incorrect because &ldquo;therefore&rdquo; illogically signals that the discovery about jorō spiders&rsquo; gentleness is a result of the initial hypothesis about their aggressive behavior. Instead, the sentence presents information that contradicts the initial hypothesis. Choice C is incorrect because &ldquo;for example&rdquo; illogically signals that the discovery about jorō spiders&rsquo; gentleness exemplifies the initial hypothesis about their aggressive behavior. Instead, the sentence presents information that contradicts the initial hypothesis. Choice D is incorrect because &ldquo;in other words&rdquo; illogically signals that the discovery about jorō spiders&rsquo; gentleness is merely restating or rephrasing the initial hypothesis about their aggressive behavior. Instead, the sentence presents information that contradicts the initial hypothesis.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$bfb4e85e$SATQ$, $SATQ$808dc1ee-2be6-4bb1-b3c9-42b468c3ecf2$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Ballet dancer Misty Copeland has accomplished a lot. She has appeared on Broadway, toured with Prince, and even served on the President&rsquo;s Council on Sports, Fitness &amp; Nutrition. <span aria-hidden="true">______</span><span class="sr-only">blank</span> according to Copeland, nothing in her career matches the honor of being the first African American woman named principal dancer at the prestigious American Ballet Theatre.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"40c74578-b966-4b6a-8b0c-322ff9e6281a","content":"<p>Thus,</p>"},{"id":"e0f9bb3c-35a7-4338-84f5-15e1472090ad","content":"<p>However,</p>"},{"id":"0e189887-8cf9-416b-be45-8a36ebccd9d4","content":"<p>For example,</p>"},{"id":"bade8206-be9b-4e20-91b7-e190e5777d7c","content":"<p>Second of all,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["e0f9bb3c-35a7-4338-84f5-15e1472090ad"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. "However" logically signals that the information in this sentence&mdash;that nothing in Copeland&rsquo;s career matches her accomplishment of being the first African American woman named principal dancer at the American Ballet Theatre&mdash;offers a contrast or exception to the previous information about Copeland&rsquo;s accomplishments.</p><p>Choice A is incorrect because "thus" illogically signals that the information that follows is a result of the previous information about Copeland&rsquo;s accomplishments. Instead, the statement that nothing in Copeland&rsquo;s career matches this accomplishment offers a contrast or exception to that information. Choice C is incorrect because "for example" illogically signals that Copeland&rsquo;s statement about her greatest accomplishment exemplifies the claim about her accomplishments in the previous sentence. Instead, it offers a contrast or exception to that information. Choice D is incorrect because "second of all" illogically signals that the information in this sentence is a second, separate claim from the previous sentence&rsquo;s information about her accomplishments. Instead, the statement that nothing in Copeland&rsquo;s career matches this accomplishment offers a contrast or exception to that information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"bfb4e85e","external_id":"808dc1ee-2be6-4bb1-b3c9-42b468c3ecf2","vaultid":null,"uId":"dc1a88ca-b737-439b-b35b-95f8c1a8c602","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Ballet dancer Misty Copeland has accomplished a lot. She has appeared on Broadway, toured with Prince, and even served on the President&rsquo;s Council on Sports, Fitness &amp; Nutrition. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> according to Copeland, nothing in her career matches the honor of being the first African American woman named principal dancer at the prestigious American Ballet Theatre.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"40c74578-b966-4b6a-8b0c-322ff9e6281a","content":"<p>Thus,</p>"},{"id":"e0f9bb3c-35a7-4338-84f5-15e1472090ad","content":"<p>However,</p>"},{"id":"0e189887-8cf9-416b-be45-8a36ebccd9d4","content":"<p>For example,</p>"},{"id":"bade8206-be9b-4e20-91b7-e190e5777d7c","content":"<p>Second of all,</p>"}],"keys":["e0f9bb3c-35a7-4338-84f5-15e1472090ad"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. \"However\" logically signals that the information in this sentence&mdash;that nothing in Copeland&rsquo;s career matches her accomplishment of being the first African American woman named principal dancer at the American Ballet Theatre&mdash;offers a contrast or exception to the previous information about Copeland&rsquo;s accomplishments.</p><p>Choice A is incorrect because \"thus\" illogically signals that the information that follows is a result of the previous information about Copeland&rsquo;s accomplishments. Instead, the statement that nothing in Copeland&rsquo;s career matches this accomplishment offers a contrast or exception to that information. Choice C is incorrect because \"for example\" illogically signals that Copeland&rsquo;s statement about her greatest accomplishment exemplifies the claim about her accomplishments in the previous sentence. Instead, it offers a contrast or exception to that information. Choice D is incorrect because \"second of all\" illogically signals that the information in this sentence is a second, separate claim from the previous sentence&rsquo;s information about her accomplishments. Instead, the statement that nothing in Copeland&rsquo;s career matches this accomplishment offers a contrast or exception to that information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323042,"updateDate":1730147323042}$SATQ$::jsonb, 1730147323042, 1730147323042)
